/**
 * 渲染层源码常量（自动生成，请勿手改）。
 *
 * 来源：src/video-remotion/src/character、src/video-remotion/src/three
 * 重生成：cd src/backend && npm run sync:three-stage
 *
 * 生成任务目录时由 video-generation-agent.service.ts 逐个写入（路径与源目录一致），
 * 模板只负责 import。用 JSON 字符串字面量而不是模板字符串：源码里的反引号、
 * ${}、反斜杠都不用再转义。
 */

export type StageTemplateFile = { path: string; content: string };

export const STAGE_TEMPLATE_FILES: StageTemplateFile[] = [
  {
    "path": "character/pose.ts",
    "content": "/**\r\n * 姿态中枢：与渲染器无关的动作解算\r\n *\r\n * 这个文件是\"角色怎么动\"的唯一真源。它只输出关节目标点，不碰任何渲染 API：\r\n *  - 3D 舞台（three/ThreeActionStage.tsx）把目标点映射到圆柱与四元数；\r\n *  - 2D 角色（character/Puppet2D.tsx）把目标点投影到 SVG 分片；\r\n *  - 以后要加渲染器，只写投影，不写动作。\r\n *\r\n * 坐标系（两个渲染器共用，2D 只取 x/y 并翻转 y）：\r\n *  - 原点在髋部中心，y 向上，单位是\"角色高度\"的归一化世界单位；\r\n *  - 站立时髋部在 y=0.66，脚底约 -0.64；\r\n *  - z 只影响景深与遮挡顺序，2D 用它做左右/前后的小幅错位。\r\n *\r\n * 为什么动作写死在代码里、而参数开放给模型：\r\n * pose() 每帧都要算、必须确定、出错必须可降级——这类东西交给模型现算，\r\n * 换来的是不确定的渲染结果和静默失败。模型该做的是选原语、给参数、给关键帧，\r\n * 那是\"编排\"；这里提供的是\"运动学词汇表\"。新增原语 = 在这个文件加一个函数。\r\n */\r\n\r\nexport type Tri = [number, number, number];\r\n\r\nexport const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));\r\nexport const lerp = (a: number, b: number, t: number) => a + (b - a) * t;\r\nexport const smooth = (t: number) => t * t * (3 - 2 * t);\r\n\r\n/** 角色尺寸（局部坐标，原点在髋部中心） */\r\nexport const SPEC = {\r\n  hipY: 0,\r\n  torsoR: 0.3,\r\n  shoulder: [0.28, 0.42, 0.02] as Tri,\r\n  hipJoint: [0.14, -0.12, 0] as Tri,\r\n  /** 手臂/腿的最大伸展（站姿距离约 0.45 / 0.50，留一点余量，否则会被钳制） */\r\n  armLen: 0.54,\r\n  legLen: 0.52,\r\n  headY: 0.72,\r\n  headR: 0.29,\r\n  /** 站立时髋部离地高度：脚底 -0.64 + 0.02 间隙 */\r\n  standHipY: 0.66,\r\n};\r\n\r\n/** 球半径（注册表是权威值，这里只给渲染兜底） */\r\nexport const BALL_RADIUS = 0.26;\r\n\r\n/**\r\n * 坐滑梯时髋部沿滑面法线抬起的距离（躯干底 -0.28 刚好压在滑面上）。\r\n * 布景注册表要算\"坐在平台上的角色头顶有多高\"，必须用同一个数，\r\n * 所以从这里导出，不在 setpiece.ts 里另抄一份。\r\n */\r\nexport const SLIDE_SEAT_LIFT = 0.27;\r\n\r\n/** 角色造型参数：两个渲染器共用同一份，造型改一次两边一起变 */\r\nexport type ActorRig = {\r\n  fur: string;\r\n  belly: string;\r\n  ears: 'round' | 'long' | 'pointy' | 'flap' | 'none';\r\n  tail: 'stub' | 'long' | 'bushy';\r\n  scale: number;\r\n};\r\n\r\nexport type Pose = {\r\n  root: Tri;\r\n  /** 躯干倾角（弧度），正数为前倾 */\r\n  rotZ: number;\r\n  /** 朝向：0 正对镜头，±π 背对；2D 用它决定左右翻转 */\r\n  rotY: number;\r\n  /** 以下四点都是相对髋部的局部坐标 */\r\n  handL: Tri;\r\n  handR: Tri;\r\n  footL: Tri;\r\n  footR: Tri;\r\n  tailSwing: number;\r\n  headTilt: number;\r\n  squash: number;\r\n};\r\n\r\n/** 静止站姿的四肢位置，所有动作都以它为基准混合 */\r\nexport const STAND_POSE: Omit<Pose, \"root\"> = {\r\n  rotZ: 0,\r\n  rotY: 0,\r\n  handL: [-0.36, -0.02, 0.06],\r\n  handR: [0.36, -0.02, 0.06],\r\n  footL: [-0.16, -0.62, 0.02],\r\n  footR: [0.16, -0.62, 0.02],\r\n  tailSwing: 0,\r\n  headTilt: 0,\r\n  squash: 1,\r\n};\r\n\r\n/**\r\n * 两个姿态之间的线性混合（t=0 取 a，t=1 取 b）。\r\n *\r\n * 用途是一幕多动作的**段落接缝**：走路末帧手臂在体侧，point 首帧手臂已平举，\r\n * 硬切会\"啪\"地跳一下。混合的是关节目标点，不是渲染结果——所以 2D 的两段肢体\r\n * 求解、3D 的圆柱朝向都会自动跟上，不需要各自再写一份过渡。\r\n *\r\n * 不做弧线插值、不处理重心偏移：姿态差本来就是给人看的过渡，8 帧内线性足够；\r\n * 弧线会让\"抬手\"变成\"绕身体划一圈\"，反而更假。\r\n */\r\nexport function blendPose(a: Pose, b: Pose, t: number): Pose {\r\n  const k = clamp(t, 0, 1);\r\n  const mix = (x: number, y: number) => x + (y - x) * k;\r\n  const mixPoint = (x: Tri, y: Tri): Tri => [mix(x[0], y[0]), mix(x[1], y[1]), mix(x[2], y[2])];\r\n  return {\r\n    root: mixPoint(a.root, b.root),\r\n    rotZ: mix(a.rotZ, b.rotZ),\r\n    rotY: mix(a.rotY, b.rotY),\r\n    handL: mixPoint(a.handL, b.handL),\r\n    handR: mixPoint(a.handR, b.handR),\r\n    footL: mixPoint(a.footL, b.footL),\r\n    footR: mixPoint(a.footR, b.footR),\r\n    tailSwing: mix(a.tailSwing, b.tailSwing),\r\n    headTilt: mix(a.headTilt, b.headTilt),\r\n    squash: mix(a.squash, b.squash),\r\n  };\r\n}\r\n\r\n/**\r\n * 动作原语。这是有限集，也是\"字母表\"：\r\n * 位移 5 个、操作 5 个、手势 4 个、状态 4 个，约 18 个足以覆盖儿童教学场景。\r\n * 新动作优先走\"组合 + 参数 + 关键帧\"，只有真正新的运动学拓扑才加到这里。\r\n */\r\nexport const MOTION_OPS = [\r\n  'idle',\r\n  'speak',\r\n  'point',\r\n  'walk',\r\n  'enter',\r\n  'climb',\r\n  'slide',\r\n  'dribble',\r\n  'cheer',\r\n  'sit',\r\n] as const;\r\nexport type MotionOp = (typeof MOTION_OPS)[number];\r\n\r\n/** 动作输入：只含运动学需要的字段，渲染相关的（配色/名条/素材）不在这里 */\r\nexport type MotionInput = {\r\n  motion: MotionOp;\r\n  durationFrames: number;\r\n  /** 世界坐标轨迹端点，y 向上 */\r\n  start?: Tri;\r\n  end?: Tri;\r\n  bounce?: { periodFrames: number; height: number };\r\n  ballRestY?: number;\r\n  /** climb：阶梯数量 */\r\n  steps?: number;\r\n};\r\n\r\nconst mixTri = (a: Tri, b: Tri, t: number): Tri => [\r\n  lerp(a[0], b[0], t),\r\n  lerp(a[1], b[1], t),\r\n  lerp(a[2], b[2], t),\r\n];\r\n\r\n/** 把一段位移曲线（0..1）映射到起终点之间 */\r\nconst alongPath = (start: Tri, end: Tri, t: number): Tri => mixTri(start, end, t);\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 状态类：站着、说话、欢呼、坐下\r\n * ------------------------------------------------------------------ */\r\n\r\nfunction idlePose(frame: number, amp = 1): Pose {\r\n  // 呼吸：4 秒一个来回，起伏 1.2cm，肉眼刚好能看出\"活着\"\r\n  const breath = Math.sin(frame / 14) * 0.012 * amp;\r\n  return {\r\n    root: [0, SPEC.standHipY + breath, 0],\r\n    rotZ: 0,\r\n    rotY: 0,\r\n    handL: [STAND_POSE.handL[0], STAND_POSE.handL[1] + breath * 0.5, STAND_POSE.handL[2]],\r\n    handR: [STAND_POSE.handR[0], STAND_POSE.handR[1] + breath * 0.5, STAND_POSE.handR[2]],\r\n    footL: STAND_POSE.footL,\r\n    footR: STAND_POSE.footR,\r\n    tailSwing: Math.sin(frame / 11) * 0.25,\r\n    headTilt: Math.sin(frame / 20) * 0.03,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\nfunction speakPose(frame: number): Pose {\r\n  const base = idlePose(frame, 0.8);\r\n  // 说话的手势：右手抬起做强调，跟着语气分句起伏（不是匀速摆）\r\n  const beat = Math.sin(frame / 6);\r\n  const lift = Math.max(0, Math.sin(frame / 9));\r\n  return {\r\n    ...base,\r\n    handR: [0.4, -0.02 + lift * 0.26, 0.14 + beat * 0.03],\r\n    // 点头幅度比 idle 大：说话时头部是最先被注意到的地方\r\n    headTilt: Math.sin(frame / 8) * 0.06,\r\n  };\r\n}\r\n\r\n/**\r\n * 指认：右臂向侧前方平伸，指尖略高于肩，手腕有细小抖动。\r\n *\r\n * 单独一个原语而不是复用 speak 的抬手，因为两者在孩子眼里是两件事：\r\n * speak 是\"我在说\"，手在身前比划；point 是\"看那个\"，手臂明确指向画面另一侧\r\n * 的道具。合成一个动作会让\"指着滑梯\"看起来像\"在滑梯旁边自言自语\"。\r\n */\r\nfunction pointPose(frame: number): Pose {\r\n  const base = idlePose(frame, 0.7);\r\n  // 持续平举会像假人，加一个幅度很小、周期较慢的呼吸式浮动\r\n  const drift = Math.sin(frame / 16) * 0.025;\r\n  const wobble = Math.sin(frame / 9) * 0.012;\r\n  return {\r\n    ...base,\r\n    // 手臂要接近水平（肩在 y=0.42），并且 x 伸到躯干轮廓之外（半径 0.3），\r\n    // 否则手掌会被躯干吃掉，画面上只剩躯干侧面鼓出一个疙瘩。\r\n    handR: [0.78, 0.34 + drift, 0.2 + wobble],\r\n    // 左臂自然下垂略后摆：x 不能收到 -0.26 以内，那会让上臂折进身体\r\n    handL: [-0.34, -0.06, 0.04],\r\n    // 上半身朝指向侧轻微侧倾：孩子读\"指着那边\"主要看身体朝向，不看手指\r\n    rotZ: -0.04 + drift * 0.4,\r\n    headTilt: -0.04,\r\n  };\r\n}\r\n\r\nfunction cheerPose(frame: number): Pose {\r\n  const base = idlePose(frame, 0.6);\r\n  // 双手举高 + 弹跳，庆祝类分镜用\r\n  const hop = Math.abs(Math.sin(frame / 7));\r\n  return {\r\n    ...base,\r\n    root: [0, SPEC.standHipY + hop * 0.12, 0],\r\n    handL: [-0.42, 0.5 + hop * 0.08, 0.1],\r\n    handR: [0.42, 0.5 + hop * 0.08, 0.1],\r\n    footL: [-0.18, -0.62 + hop * 0.1, 0.02],\r\n    footR: [0.18, -0.62 + hop * 0.1, 0.02],\r\n    headTilt: -0.1,\r\n    tailSwing: Math.sin(frame / 6) * 0.5,\r\n  };\r\n}\r\n\r\nfunction sitPose(frame: number): Pose {\r\n  const swing = Math.sin(frame / 9) * 0.05;\r\n  return {\r\n    root: [0, SPEC.standHipY - 0.26, 0],\r\n    rotZ: 0,\r\n    rotY: 0,\r\n    handL: [-0.34, 0.06 + swing * 0.4, 0.18],\r\n    handR: [0.34, 0.06 - swing * 0.4, 0.18],\r\n    // 坐着时腿向前伸，脚落在身体前方\r\n    footL: [0.24, -0.3, -0.12],\r\n    footR: [0.24, -0.3, 0.12],\r\n    tailSwing: Math.sin(frame / 10) * 0.3,\r\n    headTilt: 0,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 位移类：走、入场、爬\r\n * ------------------------------------------------------------------ */\r\n\r\n/**\r\n * 走路：双腿反相摆动，双臂与对侧腿同相。\r\n * 关键不是\"位移多少\"，而是\"支撑脚在地面不动、摆动脚离地\"——\r\n * 前者决定看起来像不像滑行，后者决定有没有\"一步一步\"的节奏。\r\n */\r\nfunction walkPose(input: MotionInput, frame: number, cycles = 2.4): Pose {\r\n  const dur = Math.max(12, input.durationFrames || 90);\r\n  const u = clamp(frame / dur, 0, 1);\r\n  const start = input.start ?? [0, SPEC.standHipY, 0];\r\n  const end = input.end ?? [0, SPEC.standHipY, 0];\r\n  // 起止各留 12% 做加减速：匀速走像传送带\r\n  const travel = smooth(clamp((u - 0.06) / 0.86, 0, 1));\r\n  const root = alongPath(start, end, travel);\r\n\r\n  const legPhase = 2 * Math.PI * cycles * u;\r\n  const swingL = Math.sin(legPhase);\r\n  const swingR = Math.sin(legPhase + Math.PI);\r\n  // 抬脚只取正半周：脚在地面时不上下飘\r\n  const liftL = Math.max(0, swingL) * 0.15;\r\n  const liftR = Math.max(0, swingR) * 0.15;\r\n  // 身体上下：一个步幅两次起伏（双脚各一次支撑）\r\n  const bob = Math.abs(Math.sin(legPhase)) * 0.022;\r\n\r\n  return {\r\n    root: [root[0], root[1] + bob, root[2]],\r\n    rotZ: 0.04,\r\n    rotY: 0,\r\n    handL: [-0.36 + swingR * 0.12, -0.02 + Math.abs(swingR) * 0.03, 0.06],\r\n    handR: [0.36 + swingL * 0.12, -0.02 + Math.abs(swingL) * 0.03, 0.06],\r\n    // 2D 是正面视角，\"前后\"没有第三个维度可表现：脚如果左右摆到 ±0.2，\r\n    // 会和 ±0.16 的基础站距抵消、两腿交叉成一坨。所以横向几乎不动，\r\n    // 走路全靠\"抬脚交替\"与身体起伏来读——这是正面视角唯一诚实的手段。\r\n    footL: [-0.17, -0.62 + liftL, 0.02],\r\n    footR: [0.17, -0.62 + liftR, 0.02],\r\n    tailSwing: Math.sin(legPhase * 0.5) * 0.35,\r\n    headTilt: Math.sin(legPhase) * 0.04,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/** 入场：和走路同一套腿部节奏，但带淡入感——前 8 帧重心略低，像刚迈进来 */\r\nfunction enterPose(input: MotionInput, frame: number): Pose {\r\n  const walk = walkPose(input, frame, 2.0);\r\n  const settle = smooth(clamp(frame / 18, 0, 1));\r\n  return {\r\n    ...walk,\r\n    root: [walk.root[0], walk.root[1] - (1 - settle) * 0.05, walk.root[2]],\r\n    headTilt: walk.headTilt - (1 - settle) * 0.1,\r\n  };\r\n}\r\n\r\n/**\r\n * 爬梯子：这是\"爬上滑梯\"需要的那个动作，也是 2D 之前完全缺失的表达。\r\n *\r\n * 三条规则让它读起来像\"爬\"而不是\"向上飘\"：\r\n *  1. 上升是离散的——重心按阶跳，每阶内部用 smooth 过渡，视觉上有停顿；\r\n *  2. 手脚交替——一侧脚抬起时，对侧手在向上够（同手同脚会像僵尸）；\r\n *  3. 身体前倾——贴着梯子，不是直立在旁边。\r\n */\r\nfunction climbPose(input: MotionInput, frame: number): Pose {\r\n  const dur = Math.max(24, input.durationFrames || 120);\r\n  const u = clamp(frame / dur, 0, 1);\r\n  const steps = Math.max(1, Math.round(input.steps ?? 4));\r\n  // 末 12% 停在顶端站稳，不然最后一帧还在动\r\n  const p = clamp(u / 0.88, 0, 1) * steps;\r\n  const k = Math.min(steps - 1, Math.floor(p));\r\n  const phase = clamp(p - k, 0, 1);\r\n  const progress = clamp((k + smooth(phase)) / steps, 0, 1);\r\n\r\n  const start = input.start ?? [-0.55, SPEC.standHipY, 0];\r\n  const end = input.end ?? [-0.55, SPEC.standHipY + 0.84, 0];\r\n  const root = alongPath(start, end, progress);\r\n  const stepH = Math.max(0.05, (end[1] - start[1]) / steps);\r\n\r\n  // 每阶换主导侧：同手同脚看起来像僵尸\r\n  const lead = k % 2 === 0 ? 1 : -1;\r\n  // 两只手脚各有相位，副侧落后半阶，形成\"抓—拉—换\"的交替\r\n  const phaseLead = phase;\r\n  const phaseTrail = (phase + 0.5) % 1;\r\n\r\n  /**\r\n   * 手为什么不是\"相对髋部固定\"：\r\n   * 手抓住横档之后，横档在世界里不动，身体往上走 → 手相对髋部越来越低，\r\n   * 手臂从伸直变成弯曲；跨到下一阶时手跳到上一根横档，重新伸直。\r\n   * 如果让 hand 相对髋部恒定，画面上就是\"手黏在梯子上跟身体一起滑\"，\r\n   * 完全没有\"一把一把往上抓\"的感觉。这是爬梯最关键的一条。\r\n   */\r\n  const gripY = (ph: number) => 0.88 - ph * stepH;\r\n  // 另一只手在换手：从上一档松手，收到胸前再抓上去\r\n  const reachY = (ph: number) => 0.46 - ph * stepH * 0.6;\r\n\r\n  const handLead: Tri = [lead * 0.44, gripY(phaseLead), 0.18];\r\n  const handTrail: Tri = [-lead * 0.44, reachY(phaseTrail), 0.12];\r\n\r\n  // 脚：踩住的那只不抬，抬起的那只收到脚踝高度再踩下一档\r\n  const stepLift = (ph: number) => Math.max(0, Math.sin(Math.PI * ph)) * 0.2;\r\n  const footLeadY = -0.62 + stepLift(phaseLead) * (phaseLead < 0.5 ? 1 : 0.2);\r\n  const footTrailY = -0.62 + stepLift(phaseTrail) * (phaseTrail < 0.5 ? 1 : 0.2);\r\n\r\n  return {\r\n    root: [root[0], root[1], root[2]],\r\n    // 倾角只能很小：gripY 是按\"局部 y 差\"算的，而投影会施加 rotZ，\r\n    // 倾 18° 会把手的实际高度抬高 0.065（约两根横档间距的一半），\r\n    // 手脚于是落在横档之间——看起来就是\"手悬在半空\"。\r\n    // 爬直梯本来也接近直立，前倾由手/脚的前后位置表达，不靠整体旋转。\r\n    rotZ: 0.05 + Math.sin(p * Math.PI) * 0.02,\r\n    rotY: 0,\r\n    handL: lead > 0 ? handLead : handTrail,\r\n    handR: lead > 0 ? handTrail : handLead,\r\n    footL: [-0.17, lead > 0 ? footLeadY : footTrailY, 0.04],\r\n    footR: [0.17, lead > 0 ? footTrailY : footLeadY, 0.04],\r\n    tailSwing: Math.sin(p * Math.PI) * 0.3,\r\n    headTilt: -0.14 + phase * 0.04,\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 滑滑梯（原有 3D 动作，逻辑一字未改，只把入参类型收窄到运动学字段）\r\n * ------------------------------------------------------------------ */\r\n\r\nexport function slidePose(input: MotionInput, frame: number): Pose {\r\n  const dur = Math.max(24, input.durationFrames || 90);\r\n  const u = clamp(frame / dur, 0, 1);\r\n  // 加速度曲线：起滑慢、中段快、到底前不再加速（u^1.5 而不是线性）\r\n  const travel = Math.pow(u, 1.5);\r\n\r\n  const start = input.start ?? [-3.1, 2.7, 0];\r\n  const end = input.end ?? [2.9, 0.3, 0];\r\n  const sx = start[0];\r\n  const sy = start[1];\r\n  const ex = end[0];\r\n  const ey = end[1];\r\n  const dx = ex - sx;\r\n  const dy = ey - sy;\r\n  const len = Math.sqrt(dx * dx + dy * dy) || 1;\r\n  const nx = -dy / len;\r\n  const ny = dx / len;\r\n  const angle = Math.atan2(dy, dx);\r\n\r\n  // 沿滑面 4% → 96%：起点落在平台上，终点停在滑面底端\r\n  const p = lerp(0.04, 0.96, travel);\r\n  const px = sx + dx * p;\r\n  const py = sy + dy * p;\r\n\r\n  // 坐姿：髋部沿法线抬起 SLIDE_SEAT_LIFT（躯干底 -0.28 刚好压在滑面上），双腿沿滑面\r\n  // 向前伸出而不是垂到板下面——垂下去会被滑板挡住，看起来像\"浮在板上\"。\r\n  const slideRoot: Tri = [px + nx * SLIDE_SEAT_LIFT, py + ny * SLIDE_SEAT_LIFT, 0];\r\n  const swing = Math.sin(frame / 5) * 0.06;\r\n  const sitting: Omit<Pose, \"root\"> = {\r\n    rotZ: angle + 0.1,\r\n    rotY: 0,\r\n    handL: [-0.4, 0.74 + swing, 0.2],\r\n    handR: [0.4, 0.74 - swing, 0.2],\r\n    footL: [0.5, 0.12 + swing * 0.5, -0.14],\r\n    footR: [0.5, 0.12 - swing * 0.5, 0.14],\r\n    tailSwing: Math.sin(frame / 8) * 0.5,\r\n    headTilt: -0.12,\r\n    squash: 1,\r\n  };\r\n\r\n  // 最后一程站起来：坐姿 → 站姿，位置从滑面底端落到地面\r\n  const standT = smooth(clamp((u - 0.9) / 0.1, 0, 1));\r\n  // 落地点要离开滑道末端：贴着末端站会和斜板叠在一起，像被插穿\r\n  const standRoot: Tri = [ex + 0.8, SPEC.standHipY, 0];\r\n  const root: Tri = [\r\n    lerp(slideRoot[0], standRoot[0], standT),\r\n    lerp(slideRoot[1], standRoot[1], standT),\r\n    lerp(slideRoot[2], standRoot[2], standT),\r\n  ];\r\n\r\n  return {\r\n    root,\r\n    rotZ: lerp(sitting.rotZ, STAND_POSE.rotZ, standT),\r\n    rotY: 0,\r\n    handL: mixTri(sitting.handL, STAND_POSE.handL, standT),\r\n    handR: mixTri(sitting.handR, STAND_POSE.handR, standT),\r\n    footL: mixTri(sitting.footL, STAND_POSE.footL, standT),\r\n    footR: mixTri(sitting.footR, STAND_POSE.footR, standT),\r\n    tailSwing: lerp(sitting.tailSwing, 0, standT),\r\n    headTilt: lerp(sitting.headTilt, 0, standT),\r\n    squash: 1,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 拍球\r\n *\r\n * 接触关系是这一段的核心：球的 Y 由周期函数给出，接触帧固定在周期边界；\r\n * 熊掌目标点 = 球心 + 0.9R（搭在球顶），手臂用\"肩→目标\"定向自动跟手。\r\n * 因此\"掌球同帧接触\"不是靠调参对齐两条时间线，而是同一个变量算出来的。\r\n * ------------------------------------------------------------------ */\r\n\r\nexport function dribblePose(\r\n  input: MotionInput,\r\n  frame: number,\r\n): { pose: Pose; ball: Tri; squash: number; spin: number } {\r\n  const period = Math.max(6, input.bounce?.periodFrames ?? 18);\r\n  const height = Math.max(0.2, input.bounce?.height ?? 0.62);\r\n  const rest = input.ballRestY ?? 0.27;\r\n  const radius = BALL_RADIUS;\r\n\r\n  const cyclePhase = (((frame % period) + period) % period) / period;\r\n  const lift = Math.abs(Math.sin(Math.PI * cyclePhase));\r\n  const ballY = rest + height * lift;\r\n\r\n  // 球在小熊右侧、同一景深平面内：再往前放会让手臂藏在球后面，\r\n  // 孩子看到的是\"一颗球悬在耳边\"，不是\"熊掌在拍球\"。\r\n  const ballX = 0.72;\r\n  const ballZ = 0.15;\r\n  const ball: Tri = [ballX, ballY, ballZ];\r\n\r\n  // 落地附近压扁，最高点恢复\r\n  const contact = clamp(1 - (ballY - rest) / 0.14, 0, 1);\r\n  const squash = 1 - 0.12 * contact;\r\n  const spin = frame * 0.1;\r\n\r\n  // 身体随球起伏：球到手边时微微下蹲，球飞起时站直\r\n  const hipY = SPEC.standHipY - 0.07 * (1 - lift);\r\n  const root: Tri = [0, hipY, 0];\r\n\r\n  // 右掌搭在球顶靠前的一侧（z 比球心大 0.11）：既真实接触又不被球挡住。\r\n  // 目标点 = 球心 + 0.9R，臂长 0.54 覆盖得了这个范围，所以不会被拉伸。\r\n  const handR: Tri = [ballX, ballY + radius * 0.9 - hipY, ballZ + 0.11];\r\n  // 左臂自然摆动配平\r\n  const handL: Tri = [-0.38, -0.02 + Math.sin(frame / 7) * 0.05, 0.08];\r\n  // 脚随下蹲略微屈膝\r\n  const kneeDrop = 0.07 * (1 - lift);\r\n  const footL: Tri = [-0.16, -0.62 + kneeDrop, 0.02];\r\n  const footR: Tri = [0.16, -0.62 + kneeDrop, 0.02];\r\n\r\n  return {\r\n    pose: {\r\n      root,\r\n      rotZ: 0,\r\n      // 身体正对镜头：转身体会把手臂目标点一起转走，掌心就贴不到球了\r\n      rotY: 0,\r\n      handL,\r\n      handR,\r\n      footL,\r\n      footR,\r\n      tailSwing: Math.sin(frame / 9) * 0.35,\r\n      headTilt: 0.18 + lift * 0.05,\r\n      squash: 1,\r\n    },\r\n    ball,\r\n    squash,\r\n    spin,\r\n  };\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 分发：新增原语只在这里加一行，渲染器不动\r\n * ------------------------------------------------------------------ */\r\n\r\nexport function poseAt(input: MotionInput, frame: number): Pose {\r\n  switch (input.motion) {\r\n    case 'slide':\r\n      return slidePose(input, frame);\r\n    case 'dribble':\r\n      return dribblePose(input, frame).pose;\r\n    case 'walk':\r\n      return walkPose(input, frame);\r\n    case 'enter':\r\n      return enterPose(input, frame);\r\n    case 'climb':\r\n      return climbPose(input, frame);\r\n    case 'speak':\r\n      return speakPose(frame);\r\n    case 'point':\r\n      return pointPose(frame);\r\n    case 'cheer':\r\n      return cheerPose(frame);\r\n    case 'sit':\r\n      return sitPose(frame);\r\n    case 'idle':\r\n    default:\r\n      return idlePose(frame);\r\n  }\r\n}\r\n\r\n/** 这个原语需要哪些运动学参数（给后端做可演性校验用） */\r\nexport const MOTION_REQUIRES: Record<MotionOp, Array<keyof MotionInput>> = {\r\n  idle: [],\r\n  speak: [],\r\n  point: [],\r\n  cheer: [],\r\n  sit: [],\r\n  walk: ['start', 'end'],\r\n  enter: ['start', 'end'],\r\n  climb: ['start', 'end'],\r\n  slide: ['start', 'end'],\r\n  dribble: ['bounce'],\r\n};\r\n"
  },
  {
    "path": "character/stage-layout.ts",
    "content": "/**\n * 景别层（shot）：把\"画什么\"和\"画多大\"分开\n *\n * 这个文件解决的是同一类事故的**结构**问题，不是某一帧好看不好看：\n *\n *   - 梯子顶端被标题胶囊压住（实测：标题白底覆盖 42..121px，梯子顶端 114px）。\n *     根因不是\"梯子画高了\"，而是缩放系数 265 是个硬编码常量，和\"标题占多高\"\n *     没有任何关系——只要动作再高一点，画面就会撞上去，而改这个常量又会牵连\n *     所有场景的大小。\n *   - 二维地面 856、三维地面（lookY 反推）约 827。两边各自写死，切镜头时\n *     角色会上下跳一小格，观众说不出哪里不对，但会觉得\"闪\"。\n *   - 没有\"景别\"概念：滑梯要装下整个结构、拍球只需要装下熊、头像只需要脸，\n *     三种需求共用一套取景，只能取折中值，谁都不合适。\n *\n * 做法是一条取景定律，而不是一堆特例：\n *\n *   ppu（每世界单位多少像素）\n *     = min( 可用带高 × 该景别占比 ÷ 主体高度,\n *            可用带高 ÷ 内容世界高度 )\n *\n * 前一项决定\"主体看起来多大\"，后一项决定\"布景一次能装多高\"。\"内容世界高度\"\n * 由布景/姿态给出（见 setpiece.ts），\"可用带高\"由标题与地面给出（本文件）。\n * 于是\"主体不能高过标题\"不再是需要记得遵守的约定，而是算不出来就越界的量——\n * 内容再高，缩放自动变小。\n *\n * 三维相机不是另一套参数：给定 ppu 与地面线，相机距离与 lookY 由公式反推，\n * 保证 3D 的地面**也**落在 STAGE.groundY。这是\"2D/3D 同源\"的第一层。\n */\n\n/** 画面尺寸。与 Remotion composition 一致，渲染器不做第二次取整 */\nexport const STAGE = {\n  width: 1920,\n  height: 1080,\n  /** 角色横向锚点（滑梯/梯子/球都围绕它） */\n  centerX: 960,\n  /**\n   * 标题胶囊底边。不是估的：对 1080p 抽帧做像素扫描，中心 700..1250 区间里\n   * 连续白底出现在 y=42..121。改标题字号/内边距必须重测这个值。\n   */\n  titleBandBottom: 121,\n  /**\n   * 主体与标题之间至少留这么多像素。\n   * 30 而不是 20：2D 立杆是 round cap 的描边，**视觉**顶边会比几何顶端高\n   * 半个线宽（实测约 7px），只留 20 的话看起来还是贴着标题。\n   */\n  titleGap: 30,\n  /** 地面线：2D 投影与 3D 相机都对齐到这一行，切换渲染器时脚不会跳 */\n  groundY: 856,\n};\n\n/** 主体可用区域的上边界 */\nexport const SUBJECT_TOP = STAGE.titleBandBottom + STAGE.titleGap;\n/** 主体可用带高（像素） */\nexport const SUBJECT_BAND = STAGE.groundY - SUBJECT_TOP;\n\n/**\n * 景别。取值不多，因为每多一档就多一组要维护的取舍：\n *  - wide：动作幕。主体仍是\"中景大小\"，但**必须装下布景**（梯子、滑梯），\n *    装不下就自动往后退——全景是\"为布景让路\"的结果，不是无条件缩小。\n *  - medium：单角色动作的默认档，角色约占可用带高 62%（与既有成片一致）。\n *  - close：面孔/情绪/说话。角色占满带高，脚仍踩在地面线上。\n */\nexport type Shot = 'wide' | 'medium' | 'close';\n\n/** 每个景别里\"主体占可用带高的比例\" */\nconst SHOT_FILL: Record<Shot, number> = { wide: 0.62, medium: 0.62, close: 0.92 };\n\n/** 缩放安全区：太小看不清，太大等于把角色糊在镜头上 */\nconst PPU_LIMIT = { min: 110, max: 560 };\n\n/** 三维相机：与 three/ThreeActionStage 共用，勿在别处再写一份 */\nexport const CAMERA_FOV = 40;\n\nexport type Framing = {\n  shot: Shot;\n  /** 每世界单位对应多少屏幕像素（2D 直接用它当缩放） */\n  ppu: number;\n  /** 地面在屏幕上的行（像素） */\n  groundY: number;\n  centerX: number;\n  /** 三维相机参数：由 ppu/groundY 反推，保证地面落在同一行 */\n  camera: { fov: number; z: number; lookY: number };\n};\n\nconst clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));\n\nexport type FramingInput = {\n  /**\n   * 必须完整可见的内容高度（从地面 y=0 往上），例如\"梯子顶端\"\"平台上的坐姿头顶\"。\n   * 这一项就是\"标题压角色\"那次事故的关键：当时只有角色高度，没有布景高度。\n   */\n  contentHeight: number;\n  /** 主体的世界高度（角色站高）。不给就与 contentHeight 相同 */\n  subjectHeight?: number;\n};\n\n/**\n * 取景：ppu = min(带高 × 景别占比 ÷ 主体高度, 带高 ÷ 内容高度)\n *\n * 两个约束分别对应两件事：\n *  - 前一项是\"主体看起来多大\"（景别意图）；\n *  - 后一项是\"不许裁掉布景\"（物理约束）。\n * 取小者，于是\"远景\"永远不会比\"中景\"更近，而\"内容太高\"时全景会自然后退。\n */\nexport function framingFor(input: FramingInput, shot: Shot): Framing {\n  const content = Math.max(0.2, input.contentHeight);\n  const subject = Math.max(0.2, input.subjectHeight ?? content);\n  const ppu = clamp(Math.min((SUBJECT_BAND * SHOT_FILL[shot]) / subject, SUBJECT_BAND / content), PPU_LIMIT.min, PPU_LIMIT.max);\n  const tanHalf = Math.tan((CAMERA_FOV * Math.PI) / 360);\n  // 屏幕Y = H/2 + lookY * ppu ⇒ lookY = (地面行 - H/2) / ppu\n  return {\n    shot,\n    ppu,\n    groundY: STAGE.groundY,\n    centerX: STAGE.centerX,\n    camera: {\n      fov: CAMERA_FOV,\n      z: STAGE.height / (2 * ppu * tanHalf),\n      lookY: (STAGE.groundY - STAGE.height / 2) / ppu,\n    },\n  };\n}\n\n/**\n * 动作 → 景别。\n *\n * 判断依据是\"这个动作要装下多大的东西\"，不是\"动作名字眼熟\"：\n * 爬（梯子高过角色一倍）与滑（整条滑道）必须 wide，其余单角色动作 medium。\n * 新增动作时**必须**在这里表态，否则会落到 medium——这是刻意的：\n * 默认取\"装下角色\"，最坏情况是布景被裁一点，而不是压住标题。\n */\nconst WIDE_MOTIONS: ReadonlySet<string> = new Set(['climb', 'slide']);\n\nexport function shotForMotion(motion: string): Shot {\n  return WIDE_MOTIONS.has(motion) ? 'wide' : 'medium';\n}\n\n/**\n * 道具槽位：被指着的东西摆在哪、画多大。\n *\n * 以前这三个数写死在模板里（x:1430 / y:690 / size:280），与角色大小、地面线\n * 都没有关系：换景别后角色变高，道具还停在半空，看起来像贴在背景上的图标。\n * 现在道具底边贴地、尺寸随可用带高走，角色变大它也变大。\n *\n * side: -1 放左侧，+1 放右侧。调用方按\"角色走/站的方向\"决定，别把道具摆在\n * 角色脸前。\n */\nexport function propSlot(side: 1 | -1): { x: number; y: number; size: number } {\n  const size = SUBJECT_BAND * 0.4;\n  return { x: STAGE.centerX + side * 470, y: STAGE.groundY - size / 2, size };\n}\n\n/**\n * 头像/徽章分支的取景。\n *\n * 徽章不是世界坐标里的角色（没有脚、没有地面），所以不吃 ppu；但它同样不能\n * 侵入标题带。返回的是**布局盒**（未缩放）的位置与缩放系数：\n * 盒子底边贴地，缩放原点在底边中点，于是放大只会往上长，下沿永远在地面线上，\n * 上沿由\"带高 × 92%\"决定。模板按这个摆，别再写 top:330 / scale:1.4。\n */\nexport function portraitFraming(): {\n  /** 布局盒的上边（**缩放前**的 CSS top） */\n  top: number;\n  /** 缩放后的视觉高度 */\n  height: number;\n  /** 缩放系数，配合 transform-origin: 50% 100% */\n  scale: number;\n  centerY: number;\n} {\n  // 徽章容器的设计尺寸（Template 里 TopicVisual 的外框高度）\n  const BOX = 470;\n  const height = SUBJECT_BAND * SHOT_FILL.close;\n  return {\n    top: STAGE.groundY - BOX,\n    height,\n    scale: height / BOX,\n    centerY: STAGE.groundY - height / 2,\n  };\n}\n"
  },
  {
    "path": "character/setpiece.ts",
    "content": "/**\n * 布景注册表（setpiece）：角色能接触的东西，几何只有一份\n *\n * 为什么要有这个文件：\n *\n *   - 二维的梯子写在 Puppet2D 里、三维的滑梯写在 ThreeActionStage 里，同一个\n *     \"梯子\"两处各有一套立杆间距、横档起点、顶端余量。改一处另一处不知道，\n *     于是\"爬\"和\"滑\"看起来像两个世界的规则。\n *   - 更直接的后果是取景：要保证\"主体不越界\"，渲染层必须知道\"这一幕最高的\n *     东西有多高\"。以前这个高度是各自估的（2D 写死 1.55 上限、3D 写死 z=8），\n *     估错的直接表现就是梯子顶进标题胶囊。\n *\n * 这里的职责边界很窄：**只回答几何问题**（多高、横档多密、接触面在哪）。\n * 不画东西、不读 frame、不做插值——渲染器各自把数字翻译成 SVG 或 mesh。\n *\n * 坐标系与 pose.ts 一致：y 向上、地面 y=0、单位是\"角色高度\"的归一化世界单位。\n */\n\nimport { SPEC, SLIDE_SEAT_LIFT } from './pose';\n\n/* ------------------------------------------------------------------ *\n * 梯子（2D climb 的布景；3D 滑梯自带的爬梯也从这里取参数）\n * ------------------------------------------------------------------ */\n\nexport const LADDER = {\n  /**\n   * 两根立杆到中心的距离。2D 是正面视角，杆要分得开才看得出是梯子（0.46）；\n   * 3D 滑梯的爬梯在侧面，透视下 0.46 会宽得不像话，所以另给 sideRailHalf。\n   */\n  railHalf: 0.46,\n  sideRailHalf: 0.28,\n  /** 首根横档离地：脚底 -0.64、髋部 0.66 时，最下面那根正好在脚下方 0.06 */\n  rungStart: 0.04,\n  /** 横档再密就成了实心板，手脚也放不进去 */\n  minRungSpacing: 0.12,\n  /** 立杆顶端高出\"最后一次举手\"的距离：没有这段，爬到顶就没有可抓的了 */\n  topHeadroom: 1.25,\n  /** 立杆粗细（世界单位），2D 按缩放乘 */\n  railWidth: 0.058,\n  rungWidthRatio: 0.78,\n  /** 3D 侧视爬梯：5 根横档、杆径 0.05、横档长 0.56 */\n  sideRungs: 5,\n  sideRungStart: 0.28,\n  sidePostRadius: 0.05,\n  sideRungRadius: 0.04,\n  sideRungLength: 0.56,\n} as const;\n\n/**\n * 梯子顶端的世界高度。\n *\n * 注意这里是\"布景高度\"，不是\"角色到达高度\"——两者差 1.25，正是这个差\n * 把梯子顶送进了标题带（角色 1.5 + 头顶 1.01 = 2.51 没事，梯子 2.75 撞上）。\n */\nexport function ladderTopY(climbEndY: number): number {\n  return climbEndY + LADDER.topHeadroom;\n}\n\n/* ------------------------------------------------------------------ *\n * 滑梯（3D slide 的布景）\n * ------------------------------------------------------------------ */\n\nexport const SLIDE = {\n  /** 滑面厚度 */\n  deckThickness: 0.12,\n  /** 滑面宽度（z 方向） */\n  deckWidth: 1.4,\n  /** 两侧护边 */\n  railHalf: 0.72,\n  railHeight: 0.18,\n  railThickness: 0.1,\n  railLift: 0.09,\n  /** 顶端平台 */\n  platformWidth: 1.6,\n  platformThickness: 0.12,\n  platformInset: 0.75,\n  /** 顶端支柱：只留两根，四根会把左侧糊成栅栏 */\n  topPostRadius: 0.08,\n  topPostInset: 1.2,\n  topPostHalfZ: 0.6,\n  topPostFoot: 0.1,\n  /** 支柱中心下移一点，柱底才不会悬空 */\n  postLift: 0.06,\n  /** 底端支柱：滑道末端离地 0.3，不撑起来就是一块悬空的板 */\n  endPostRadius: 0.07,\n  endPostInset: 0.3,\n  endPostHalfZ: 0.5,\n  endPostFoot: 0.06,\n  /** 爬梯（挂在平台后侧） */\n  ladderInset: 1.5,\n  ladderFoot: 0.12,\n} as const;\n\n/**\n * 滑梯结构的最高点：平台面 + 护边。\n * 平台中心在 start[1] + platformThickness/2，护边再高出 railHeight。\n */\nexport function slideTopY(startY: number): number {\n  return startY + SLIDE.platformThickness + SLIDE.railHeight;\n}\n\n/* ------------------------------------------------------------------ *\n * \"必须完整可见\"的世界高度\n *\n * 取景唯一需要的一个数。算错它的后果不是\"画面丑一点\"，而是主体被标题盖住\n * 或角色被裁掉半截，所以这里逐项写清楚来源，不留魔法数字。\n * ------------------------------------------------------------------ */\n\n/** 角色头顶到髋部的高度（含造型缩放） */\nexport function actorHeadTop(rootY: number, scale: number): number {\n  return rootY + (SPEC.headY + SPEC.headR) * scale;\n}\n\n/** 滑梯幕：平台上的坐姿角色比结构本身还高，两者取大 */\nexport function slideWorldHeight(\n  start: readonly [number, number, number],\n  end: readonly [number, number, number],\n  scale: number,\n): number {\n  const seated = actorHeadTop(start[1] + SLIDE_SEAT_LIFT, scale);\n  // 站起身的终点也不能出画（虽然比平台低，但换参数时不受假设保护）\n  const standing = actorHeadTop(Math.max(end[1], SPEC.standHipY), scale);\n  return Math.max(slideTopY(start[1]), seated, standing);\n}\n"
  },
  {
    "path": "character/Puppet2D.tsx",
    "content": "/**\r\n * 二维全身角色（Puppet2D）\r\n *\r\n * 它解决的是\"头像徽章演不了动作\"这个断层：徽章是一个圆里放一张图，没有躯干、\r\n * 没有腿、没有可动关节，所以\"走进来\"\"爬上去\"在物理上就画不出来。\r\n *\r\n * 这里的分片与三维舞台完全同构，因为它们消费的是同一份 Pose（character/pose.ts）：\r\n *  3D 把关节目标点映射成圆柱 + 四元数，2D 映射成 SVG 线段 + 两段肢体求解。\r\n * 因此\"新增一个动作\"不需要碰这个文件——动作在 pose 层写一次，两个渲染器都能演。\r\n *\r\n * 唯一的投影约定（踩过坑）：**躯干旋转必须作用在四肢上**。\r\n * 如果只给躯干椭圆加 rotate()、四肢各自按世界坐标算，爬/滑时身体转了腿没转，\r\n * 画面上就是\"上身扭过去、下身留在原地\"。所以所有部件都先转成\"相对髋部的\r\n * 局部坐标\"，由同一个 project() 统一施加 rotZ，再翻 y、缩放。\r\n *\r\n * 确定性：只用传入的 frame，不读 useCurrentFrame、不用 Math.random。\r\n */\r\n\r\nimport React from 'react';\r\nimport {\r\n  BALL_RADIUS,\r\n  SPEC,\r\n  blendPose,\r\n  clamp,\r\n  dribblePose,\r\n  poseAt,\r\n  type ActorRig,\r\n  type MotionInput,\r\n  type MotionOp,\r\n  type Pose,\r\n  type Tri,\r\n} from './pose';\r\nimport { framingFor, shotForMotion, type Shot } from './stage-layout';\r\nimport { LADDER, actorHeadTop, ladderTopY } from './setpiece';\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 取景\r\n *\r\n * 这里**没有** PPU / GROUND_Y 常量了。以前写死 PPU=265、GROUND_Y=856，\r\n * 与\"标题占多高、布景有多高\"毫无关系：梯子顶到 2.75 世界单位时，\r\n * 856 − 2.75×265 = 114px，正好钻进标题胶囊（底边 121）。\r\n *\r\n * 现在缩放由 stage-layout 的取景定律算出来：先问\"这一幕最高的东西有多高\"\r\n * （布景注册表回答），再和\"角色该画多大\"取小者。内容再高，缩放自动变小，\r\n * 撞标题这件事在算术上不成立。\r\n * ------------------------------------------------------------------ */\r\n/** climb 的角色最高点：动作设计值（4 阶 × 0.21），不再承担\"别撞标题\"的职责 */\r\nconst MAX_STAND_Y = 1.55;\r\n\r\n/** 一幕多动作里的一节。帧数由后端的注册表按\"动作自然时长\"分配，渲染层不重算。 */\r\nexport type PuppetSegment = {\r\n  motion: MotionOp;\r\n  durationFrames: number;\r\n  start?: Tri;\r\n  end?: Tri;\r\n  steps?: number;\r\n};\r\n\r\nexport type Puppet2DScene = {\r\n  motion: MotionOp;\r\n  rig: ActorRig;\r\n  start?: Tri;\r\n  end?: Tri;\r\n  steps?: number;\r\n  bounce?: { periodFrames: number; height: number };\r\n  ballRestY?: number;\r\n  durationFrames: number;\r\n  /**\r\n   * 一幕多动作的播放表，按顺序播放。长度大于 1 时 `motion` 只作为兜底\r\n   * （例如序列为空的那一帧），实际姿态由当前所在的段落决定。\r\n   */\r\n  sequence?: PuppetSegment[];\r\n  accent: string;\r\n  label?: string;\r\n  /**\r\n   * 布景道具。坐标是屏幕像素（1920×1080 画布），node 由调用方预先渲染成\r\n   * SVG 片段——组件本身不认识\"滑梯\"\"皮球\"这些业务道具，只负责把它们按\r\n   * 场景需要摆到位。这样新增道具不用改这个文件。\r\n   */\r\n  props?: Array<{ x: number; y: number; size: number; label?: string; node: React.ReactNode }>;\r\n  /** 漂浮在角色之上的覆盖层（对话气泡等 HTML 元素，不能塞进 SVG） */\r\n  overlay?: React.ReactNode;\r\n  /**\r\n   * overlay 的出场时刻（0..1，按场景进度）。用于一幕多动作：台词气泡要等到\r\n   * 说话那一段再出现，否则\"走过去→指一下→说话\"的顺序在第一帧就被剧透了。\r\n   */\r\n  overlayFrom?: number;\r\n  /**\r\n   * 景别覆盖。不给就按动作自动判定（climb → wide，其余 → medium）。\r\n   * 只影响取景，不影响动作本身：动作的世界坐标由后端定死。\r\n   */\r\n  shot?: Shot;\r\n};\r\n\r\n/** 颜色压暗：给每个形状描一圈同色深边，角色不会糊进背景 */\r\nconst shade = (hex: string, k = 0.72): string => {\r\n  const m = /^#?([0-9a-f]{6})$/i.exec(hex.trim());\r\n  if (!m) return hex;\r\n  const n = parseInt(m[1], 16);\r\n  const r = Math.round(((n >> 16) & 255) * k);\r\n  const g = Math.round(((n >> 8) & 255) * k);\r\n  const b = Math.round((n & 255) * k);\r\n  return `#${((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1)}`;\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 两段肢体求解\r\n *\r\n * 给定根关节和末端目标点，求中间关节（肘/膝）。做法是\"中点 + 法向偏移\"，\r\n * 偏移方向由 bend 的符号决定：膝盖朝前（+x），手肘朝后（-x）。\r\n * 不用真正的 IK：2D 画面上多余的自由度只会带来抖动，固定弯向才稳定。\r\n * ------------------------------------------------------------------ */\r\nfunction jointPoint(from: Tri, to: Tri, bend: number): Tri {\r\n  const mx = (from[0] + to[0]) / 2;\r\n  const my = (from[1] + to[1]) / 2;\r\n  const dx = to[0] - from[0];\r\n  const dy = to[1] - from[1];\r\n  const len = Math.sqrt(dx * dx + dy * dy) || 0.0001;\r\n  // 法向（-dy, dx）在\"末端在下方\"时指向 +x\r\n  const nx = -dy / len;\r\n  const ny = dx / len;\r\n  return [mx + nx * bend * len, my + ny * bend * len, (from[2] + to[2]) / 2];\r\n}\r\n\r\ntype Projector = (p: Tri) => [number, number];\r\n\r\n/** 上限钳制：模型/参数给的目标点再离谱，肢体也不会被拉成面条 */\r\nfunction clampReach(from: Tri, to: Tri, maxLen: number): Tri {\r\n  const dx = to[0] - from[0];\r\n  const dy = to[1] - from[1];\r\n  const dz = to[2] - from[2];\r\n  const len = Math.sqrt(dx * dx + dy * dy + dz * dz);\r\n  if (len <= maxLen) return to;\r\n  const k = maxLen / len;\r\n  return [from[0] + dx * k, from[1] + dy * k, from[2] + dz * k];\r\n}\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 部件\r\n * ------------------------------------------------------------------ */\r\n\r\nconst Limb2D: React.FC<{\r\n  pivot: Tri;\r\n  target: Tri;\r\n  bend: number;\r\n  maxLen: number;\r\n  width: number;\r\n  color: string;\r\n  capColor?: string;\r\n  capRadius?: number;\r\n  project: Projector;\r\n  /** 末端压扁比例：脚掌画扁椭圆，手掌画圆 */\r\n  capFlat?: number;\r\n}> = ({ pivot, target, bend, maxLen, width, color, capColor, capRadius, project, capFlat }) => {\r\n  const to = clampReach(pivot, target, maxLen);\r\n  const joint = jointPoint(pivot, to, bend);\r\n  const cap = capRadius ?? width * 0.62;\r\n  const capP = project(to);\r\n  const a = project(pivot);\r\n  const b = project(joint);\r\n  const c = project(to);\r\n  return (\r\n    <g>\r\n      <line x1={a[0]} y1={a[1]} x2={b[0]} y2={b[1]} stroke={color} strokeWidth={width} strokeLinecap=\"round\" />\r\n      <line x1={b[0]} y1={b[1]} x2={c[0]} y2={c[1]} stroke={color} strokeWidth={width * 0.9} strokeLinecap=\"round\" />\r\n      {capColor ? (\r\n        capFlat ? (\r\n          <ellipse\r\n            cx={capP[0]}\r\n            cy={capP[1]}\r\n            rx={cap * 1.15}\r\n            ry={cap * capFlat}\r\n            fill={capColor}\r\n            stroke={shade(capColor)}\r\n            strokeWidth={3}\r\n          />\r\n        ) : (\r\n          <circle\r\n            cx={capP[0]}\r\n            cy={capP[1]}\r\n            r={cap}\r\n            fill={capColor}\r\n            stroke={shade(capColor)}\r\n            strokeWidth={3}\r\n          />\r\n        )\r\n      ) : null}\r\n    </g>\r\n  );\r\n};\r\n\r\n/** 头：圆 + 耳 + 口鼻 + 鼻头 + 眼睛，按 headTilt 绕脖子旋转 */\r\nconst Head2D: React.FC<{ rig: ActorRig; head: [number, number]; r: number; tilt: number }> = ({\r\n  rig,\r\n  head,\r\n  r,\r\n  tilt,\r\n}) => {\r\n  const fur = rig.fur;\r\n  const belly = rig.belly;\r\n  const stroke = shade(fur);\r\n  // headTilt 是弧度，绕脖子（头底部）转，不是绕头心——绕头心转会让整颗头平移\r\n  const pivotY = head[1] + r;\r\n  const transform = `rotate(${(tilt * 180) / Math.PI} ${head[0]} ${pivotY})`;\r\n  const earY = head[1] - r * 0.74;\r\n  return (\r\n    <g transform={transform}>\r\n      {rig.ears === 'round' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <circle\r\n              key={side}\r\n              cx={head[0] + side * r * 0.62}\r\n              cy={earY}\r\n              r={r * 0.38}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n            />\r\n          ))}\r\n          {[-1, 1].map((side) => (\r\n            <circle\r\n              key={`in-${side}`}\r\n              cx={head[0] + side * r * 0.62}\r\n              cy={earY}\r\n              r={r * 0.19}\r\n              fill={belly}\r\n              opacity={0.85}\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n      {rig.ears === 'long' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <ellipse\r\n              key={side}\r\n              cx={head[0] + side * r * 0.4}\r\n              cy={earY - r * 0.6}\r\n              rx={r * 0.2}\r\n              ry={r * 0.62}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n      {rig.ears === 'pointy' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <path\r\n              key={side}\r\n              d={`M ${head[0] + side * r * 0.42} ${earY + r * 0.12} L ${head[0] + side * r * 0.78} ${earY - r * 0.52} L ${head[0] + side * r * 0.9} ${earY + r * 0.2} Z`}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n              strokeLinejoin=\"round\"\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n      {rig.ears === 'flap' ? (\r\n        <>\r\n          {[-1, 1].map((side) => (\r\n            <ellipse\r\n              key={side}\r\n              cx={head[0] + side * r * 1.14}\r\n              cy={head[1] + r * 0.06}\r\n              rx={r * 0.34}\r\n              ry={r * 0.5}\r\n              fill={fur}\r\n              stroke={stroke}\r\n              strokeWidth={3}\r\n            />\r\n          ))}\r\n        </>\r\n      ) : null}\r\n\r\n      <circle cx={head[0]} cy={head[1]} r={r} fill={fur} stroke={stroke} strokeWidth={4} />\r\n      {/* 口鼻 */}\r\n      <ellipse cx={head[0]} cy={head[1] + r * 0.34} rx={r * 0.46} ry={r * 0.34} fill={belly} />\r\n      <ellipse cx={head[0]} cy={head[1] + r * 0.18} rx={r * 0.15} ry={r * 0.11} fill=\"#3b2a20\" />\r\n      {/* 眼睛：略微内倾，比正圆更有神 */}\r\n      {[-1, 1].map((side) => (\r\n        <ellipse\r\n          key={side}\r\n          cx={head[0] + side * r * 0.36}\r\n          cy={head[1] - r * 0.12}\r\n          rx={r * 0.1}\r\n          ry={r * 0.13}\r\n          fill=\"#241812\"\r\n        />\r\n      ))}\r\n    </g>\r\n  );\r\n};\r\n\r\n/**\r\n * 梯子（climb 的布景）\r\n *\r\n * 没有它，\"爬\"在画面上就是一只浮在半空的熊——手脚找不到落点，观众读不出\r\n * 高度变化是在爬。这也是布景锚点的最小形态：道具不只是旁边摆一个图标，\r\n * 它要提供角色能够接触的表面。\r\n *\r\n * 所有几何都来自 setpiece.ts 的 LADDER：横档间距、首根位置、立杆间距。\r\n * 组件只做投影，不持有任何\"这个梯子长什么样\"的数字。\r\n */\r\nconst Ladder: React.FC<{\r\n  x: number;\r\n  baseY: number;\r\n  topY: number;\r\n  /** 横档间距：必须等于 climb 每上一阶的高度，手脚才会正好落在横档上 */\r\n  spacing: number;\r\n  project: Projector;\r\n  s: number;\r\n}> = ({ x, baseY, topY, spacing, project, s }) => {\r\n  const railHalf = LADDER.railHalf;\r\n  const wood = '#c98a5a';\r\n  const dark = '#8d5524';\r\n  const left = project([x - railHalf, baseY, 0]);\r\n  const right = project([x + railHalf, baseY, 0]);\r\n  const leftTop = project([x - railHalf, topY, 0]);\r\n  const rightTop = project([x + railHalf, topY, 0]);\r\n  const width = Math.max(9, LADDER.railWidth * s);\r\n  return (\r\n    <g>\r\n      <line x1={left[0]} y1={left[1]} x2={leftTop[0]} y2={leftTop[1]} stroke={dark} strokeWidth={width} strokeLinecap=\"round\" />\r\n      <line x1={right[0]} y1={right[1]} x2={rightTop[0]} y2={rightTop[1]} stroke={dark} strokeWidth={width} strokeLinecap=\"round\" />\r\n      {Array.from({ length: Math.max(2, Math.floor((topY - baseY) / spacing) + 1) }).map((_, i) => {\r\n        const y = baseY + LADDER.rungStart + spacing * i;\r\n        const a = project([x - railHalf, y, 0]);\r\n        const b = project([x + railHalf, y, 0]);\r\n        return (\r\n          <line\r\n            key={i}\r\n            x1={a[0]}\r\n            y1={a[1]}\r\n            x2={b[0]}\r\n            y2={b[1]}\r\n            stroke={wood}\r\n            strokeWidth={width * LADDER.rungWidthRatio}\r\n            strokeLinecap=\"round\"\r\n          />\r\n        );\r\n      })}\r\n    </g>\r\n  );\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 主组件\r\n * ------------------------------------------------------------------ */\r\n\r\nexport const Puppet2D: React.FC<{ scene: Puppet2DScene; frame: number }> = ({ scene, frame }) => {\r\n  const rig = scene.rig;\r\n  const accent = scene.accent || '#4d96ff';\r\n  const scale = rig.scale || 1;\r\n\r\n  const toInput = (seg: PuppetSegment): MotionInput => ({\r\n    motion: seg.motion,\r\n    durationFrames: Math.max(1, seg.durationFrames),\r\n    start: seg.start,\r\n    end: seg.end,\r\n    steps: seg.steps,\r\n  });\r\n\r\n  /**\r\n   * 播放表：每一段带\"入场偏移\"carry。\r\n   *\r\n   * 为什么需要 carry：walk 的默认轨迹是\"从画面左侧走到正中\"（-1.6 → 0）。\r\n   * 如果第二段 point 仍按自己的绝对原点（0）播放，角色会从走到的位置瞬移回原点；\r\n   * 反过来，如果第二段 walk 也按 -1.6 起，角色会瞬移回左侧重走一遍。\r\n   * 所以每段的**起点被安放到上一段的终点**：carry = 上一段终点 − 本段局部起点。\r\n   * 位移量仍由各段自己的 start/end 决定，注册表仍然是唯一真源。\r\n   */\r\n  type Slice = { input: MotionInput; motion: MotionOp; from: number; durationFrames: number; carry: Tri };\r\n  const single: Slice = {\r\n    input: {\r\n      motion: scene.motion,\r\n      durationFrames: Math.max(1, scene.durationFrames),\r\n      start: scene.start,\r\n      end: scene.end,\r\n      steps: scene.steps,\r\n      bounce: scene.bounce,\r\n      ballRestY: scene.ballRestY,\r\n    },\r\n    motion: scene.motion,\r\n    from: 0,\r\n    durationFrames: Math.max(1, scene.durationFrames),\r\n    carry: [0, 0, 0],\r\n  };\r\n\r\n  const plan: Slice[] = [];\r\n  if (scene.sequence && scene.sequence.length > 1) {\r\n    /**\r\n     * 拉伸系数：分镜给的时长是\"这一幕该演多久\"，而最终场景长度由**旁白音频**\r\n     * 决定（实测 8s 的幕会被拉到 8.8s）。不拉伸的后果很具体：动作在第 8 秒\r\n     * 演完，剩下的 0.8 秒角色僵在那里，而旁白还在说——观众看到的是\"卡住了\"。\r\n     * 只拉不压：场景比动作串短时宁可截掉尾巴，也不把动作挤到走形。\r\n     */\r\n    const planned = scene.sequence.reduce(\r\n      (sum, seg) => sum + Math.max(1, seg.durationFrames),\r\n      0,\r\n    );\r\n    const stretch = scene.durationFrames > planned ? scene.durationFrames / planned : 1;\r\n\r\n    let cursor: Tri | null = null;\r\n    let from = 0;\r\n    for (const seg of scene.sequence) {\r\n      const input: MotionInput = {\r\n        ...toInput(seg),\r\n        durationFrames: Math.max(1, Math.round(Math.max(1, seg.durationFrames) * stretch)),\r\n      };\r\n      const startPose = poseAt(input, 0);\r\n      const carry: Tri = cursor\r\n        ? [cursor[0] - startPose.root[0], cursor[1] - startPose.root[1], cursor[2] - startPose.root[2]]\r\n        : [0, 0, 0];\r\n      plan.push({ input, motion: seg.motion, from, durationFrames: input.durationFrames, carry });\r\n      const endPose = poseAt(input, input.durationFrames);\r\n      cursor = [\r\n        endPose.root[0] + carry[0],\r\n        endPose.root[1] + carry[1],\r\n        endPose.root[2] + carry[2],\r\n      ];\r\n      from += input.durationFrames;\r\n    }\r\n  }\r\n  if (!plan.length) plan.push(single);\r\n\r\n  const active = plan.find((slice) => frame < slice.from + slice.durationFrames) ?? plan[plan.length - 1];\r\n  // overlayFrom 是\"场景进度的比例\"，所以分母用场景帧数而不是动作串总帧数\r\n  const totalFrames = Math.max(1, scene.durationFrames);\r\n  const localFrame = clamp(frame - active.from, 0, active.durationFrames);\r\n  const activeIndex = plan.indexOf(active);\r\n  const activeMotion: MotionOp = active.motion;\r\n\r\n  const shift = (pose: Pose, carry: Tri): Pose => ({\r\n    ...pose,\r\n    root: [pose.root[0] + carry[0], pose.root[1] + carry[1], pose.root[2] + carry[2]],\r\n  });\r\n\r\n  let pose: Pose = shift(poseAt(active.input, localFrame), active.carry);\r\n  /**\r\n   * 段落接缝混合。硬切的现象很具体：走路末帧手臂在体侧、point 首帧手臂已平举，\r\n   * 一帧内跳过去，看起来像掉帧。8 帧线性混合后是\"走两步，抬手指过去\"。\r\n   * 只混姿态不混位置——位置已在 carry 里保证了连续。\r\n   */\r\n  const BLEND_FRAMES = 8;\r\n  if (activeIndex > 0 && localFrame < BLEND_FRAMES) {\r\n    const prev = plan[activeIndex - 1];\r\n    const prevPose = shift(poseAt(prev.input, prev.durationFrames), prev.carry);\r\n    const t = localFrame / BLEND_FRAMES;\r\n    pose = blendPose(prevPose, pose, t * t * (3 - 2 * t));\r\n  }\r\n\r\n  const root = pose.root;\r\n  // 拍球需要球本体：球心由同一个 dribblePose 算出，所以\"掌搭球顶\"和 3D 一样\r\n  // 是同一个变量决定的，不靠两条时间线对齐。串演序列里不会有 dribble。\r\n  const dribble =\r\n    activeMotion === 'dribble' ? dribblePose({ ...single.input, ...active.input }, localFrame) : null;\r\n\r\n  // 朝向：向右走时镜像。没有 rotY 的动作按起点→终点决定，避免\"倒着走\"\r\n  const dirX = (active.input.end?.[0] ?? 0) - (active.input.start?.[0] ?? 0);\r\n  const facing: 1 | -1 =\r\n    pose.rotY > 0.2 ? 1 : pose.rotY < -0.2 ? -1 : dirX < -0.05 ? -1 : 1;\r\n\r\n  /** 串演里的攀爬段：哪怕不是当前段，取景与梯子也要按它算 */\r\n  const climbSlice = plan.find((slice) => slice.motion === 'climb') ?? null;\r\n  const climb = !!climbSlice;\r\n  // 每上一阶的高度：横档间距与它同源，所以手/脚永远落在横档附近\r\n  const climbStep = climbSlice\r\n    ? (poseAt(climbSlice.input, climbSlice.durationFrames).root[1] -\r\n        (climbSlice.input.start?.[1] ?? SPEC.standHipY)) /\r\n      Math.max(1, climbSlice.input.steps ?? 4)\r\n    : 0.21;\r\n  // 梯子要高过举起的手（站地时手在 1.54）：否则爬到一半就没有横档可抓了\r\n  const climbEndY = climbSlice\r\n    ? poseAt(climbSlice.input, climbSlice.durationFrames).root[1] + climbSlice.carry[1]\r\n    : SPEC.standHipY + 0.84;\r\n  const ladderTop = ladderTopY(Math.min(MAX_STAND_Y, climbEndY));\r\n  /**\r\n   * 梯子挂在爬梯段的落点上，不跟当前髋部走。\r\n   * 以前写的是 x={root[0]}——单幕爬梯时两者相等所以看不出问题，\r\n   * 但\"走过去再爬\"里，走路途中梯子会跟着角色横向平移，像被拖着走。\r\n   */\r\n  const ladderX = climbSlice\r\n    ? (climbSlice.input.start?.[0] ?? 0) + climbSlice.carry[0]\r\n    : root[0];\r\n\r\n  /**\r\n   * 取景：两个数分开问。\r\n   *\r\n   *  - contentHeight = 这一幕最高的东西（爬梯时是**梯子顶端**，不是角色头）。\r\n   *    这就是以前漏掉的一项：角色 2.51、梯子 2.75，估低了 0.24 世界单位，\r\n   *    屏幕上就是 60 多像素的越界。\r\n   *  - subjectHeight = **站立身高**，只表示\"这个角色该画多大\"。用动作终点\r\n   *    的头顶高度会把\"爬得高\"误当成\"角色很大\"，全景被无谓地推远\r\n   *    （实测梯子会缩到 365px，画面空一半）。\r\n   *\r\n   * rig.scale 只按\"不小于 1\"计入：小动物画小一点是造型意图，但取景要给\r\n   * 满尺寸留够空间，否则 giraffe(1.1) 会顶出去。\r\n   */\r\n  const subjectHeight = actorHeadTop(SPEC.standHipY, Math.max(1, scale));\r\n  /**\r\n   * 这一幕最高点：取**所有段落终点**的最大值，而不是只看最后一段。\r\n   * 只看最后一段的话，\"爬上去再挥手\"这种顺序会把 1.5 的高度算漏。\r\n   */\r\n  const peakY = plan.reduce(\r\n    (top, slice) => Math.max(top, poseAt(slice.input, slice.durationFrames).root[1] + slice.carry[1]),\r\n    SPEC.standHipY,\r\n  );\r\n  const actorTop = actorHeadTop(peakY, Math.max(1, scale));\r\n  const worldHeight = climb ? Math.max(ladderTop, actorTop) : actorTop;\r\n  const shot = scene.shot ?? shotForMotion(climb ? 'climb' : activeMotion);\r\n  const framing = framingFor({ contentHeight: worldHeight, subjectHeight }, shot);\r\n\r\n  const cx = framing.centerX;\r\n  const GROUND_Y = framing.groundY;\r\n  // 角色造型缩放仍作用在角色上；取景已经为满尺寸留了空间\r\n  const s = framing.ppu * scale;\r\n\r\n  /**\r\n   * 局部坐标（相对髋部）→ 屏幕。\r\n   * 三步：绕髋部施加躯干倾角 → 加髋部世界位置 → 翻 y 并缩放。\r\n   * 所有部件（含四肢）都走这一条路，所以身体倾的时候四肢一定跟着走。\r\n   */\r\n  const cosL = Math.cos(pose.rotZ);\r\n  const sinL = Math.sin(pose.rotZ);\r\n  const project: Projector = (p) => {\r\n    const lx = p[0] * cosL - p[1] * sinL;\r\n    const ly = p[0] * sinL + p[1] * cosL;\r\n    return [cx + (root[0] + lx) * s * facing, GROUND_Y - (root[1] + ly) * s];\r\n  };\r\n\r\n  /**\r\n   * 布景投影：只做\"世界 → 屏幕\"，不施加躯干倾角。\r\n   * 梯子如果跟着角色前倾，就成了\"整个梯子被推歪\"，而不是\"熊贴着梯子\"。\r\n   */\r\n  const projectWorld: Projector = (p) => [cx + p[0] * s * facing, GROUND_Y - p[1] * s];\r\n\r\n  const head = project([0, SPEC.headY, 0.02]);\r\n  const headR = SPEC.headR * s;\r\n  const top = GROUND_Y - (root[1] + (SPEC.headY + SPEC.headR) * cosL) * s;\r\n\r\n  const bodyCenter = project([0, 0.15, 0]);\r\n  const bodyW = SPEC.torsoR * s * 0.95;\r\n  const bodyH = 0.33 * s;\r\n  const lean = (pose.rotZ * 180) / Math.PI;\r\n  const hipPoint = project([0, 0, 0]);\r\n  const torsoTransform = `rotate(${lean} ${hipPoint[0]} ${hipPoint[1]})`;\r\n  // 阴影永远在地面上，不参与角色旋转\r\n  const shadowX = cx + root[0] * s * facing;\r\n\r\n  const legColor = shade(rig.fur, 0.84);\r\n  const armColor = rig.fur;\r\n\r\n  return (\r\n    <div style={{ position: 'absolute', inset: 0 }}>\r\n      <svg\r\n        width={1920}\r\n        height={1080}\r\n        viewBox=\"0 0 1920 1080\"\r\n        style={{ position: 'absolute', inset: 0, overflow: 'visible' }}\r\n      >\r\n        {/* 道具画在角色之前：被手指着的东西应该在身体后面，不然会挡住脸 */}\r\n        {(scene.props || []).map((p, i) => (\r\n          <g key={`prop-${i}`} transform={`translate(${p.x} ${p.y})`}>\r\n            {/* node 的绘制盒子是 -80..80，按目标尺寸缩放 */}\r\n            <g transform={`scale(${p.size / 160})`}>{p.node}</g>\r\n            {p.label ? (\r\n              // 标签放道具上方：地面线以下是字幕区，写在下面会被字幕压住\r\n              <text\r\n                y={-p.size / 2 - 14}\r\n                textAnchor=\"middle\"\r\n                fontSize={34}\r\n                fontWeight={900}\r\n                fill={accent}\r\n              >\r\n                {p.label}\r\n              </text>\r\n            ) : null}\r\n          </g>\r\n        ))}\r\n\r\n        {/* 梯子必须在角色之前画（背景层），否则会盖住手脚 */}\r\n        {climb ? (\r\n          <Ladder\r\n            x={ladderX}\r\n            baseY={0}\r\n            topY={ladderTop}\r\n            spacing={Math.max(LADDER.minRungSpacing, climbStep)}\r\n            project={projectWorld}\r\n            s={s}\r\n          />\r\n        ) : null}\r\n\r\n        {/* 贴地假阴影：跟着髋部走，离地越高越淡（climb 时才明显） */}\r\n        <ellipse\r\n          cx={shadowX}\r\n          cy={GROUND_Y}\r\n          rx={Math.max(40, bodyW * 1.15)}\r\n          ry={Math.max(9, bodyW * 0.2)}\r\n          fill=\"#1b2a33\"\r\n          opacity={clamp(0.2 - (root[1] - SPEC.standHipY) * 0.26, 0.02, 0.2)}\r\n        />\r\n\r\n        {/* 远侧：先画 L，躯干与头压在上面，R 侧留到最后 */}\r\n        <Limb2D\r\n          pivot={[-SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n          target={pose.footL}\r\n          bend={0.16}\r\n          maxLen={SPEC.legLen}\r\n          width={0.18 * s}\r\n          color={legColor}\r\n          capColor={legColor}\r\n          capRadius={0.105 * s}\r\n          capFlat={0.72}\r\n          project={project}\r\n        />\r\n        <g transform={torsoTransform}>\r\n          {/* 躯干 + 肚皮 */}\r\n          <ellipse\r\n            cx={bodyCenter[0]}\r\n            cy={bodyCenter[1]}\r\n            rx={bodyW}\r\n            ry={bodyH}\r\n            fill={rig.fur}\r\n            stroke={shade(rig.fur)}\r\n            strokeWidth={4}\r\n          />\r\n          <ellipse\r\n            cx={bodyCenter[0]}\r\n            cy={bodyCenter[1] + bodyH * 0.1}\r\n            rx={bodyW * 0.6}\r\n            ry={bodyH * 0.7}\r\n            fill={rig.belly}\r\n            opacity={0.95}\r\n          />\r\n          {/* 尾巴：从躯干侧后方露出一点，纯装饰但让剪影不平 */}\r\n          <ellipse\r\n            cx={bodyCenter[0] - facing * bodyW * 0.92}\r\n            cy={bodyCenter[1] + bodyH * 0.34 + pose.tailSwing * 10}\r\n            rx={bodyW * (rig.tail === 'bushy' ? 0.32 : 0.2)}\r\n            ry={bodyH * (rig.tail === 'bushy' ? 0.28 : 0.18)}\r\n            fill={rig.tail === 'stub' ? rig.belly : rig.fur}\r\n            stroke={shade(rig.fur)}\r\n            strokeWidth={3}\r\n          />\r\n        </g>\r\n\r\n        <Head2D rig={rig} head={head} r={headR} tilt={pose.headTilt} />\r\n\r\n        {/* 手臂统一画在头之后：攀爬时手要举过头顶，压在躯干下面等于没举手 */}\r\n        <Limb2D\r\n          pivot={[-SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n          target={pose.handL}\r\n          bend={-0.16}\r\n          maxLen={SPEC.armLen}\r\n          width={0.17 * s}\r\n          color={armColor}\r\n          capColor={rig.belly}\r\n          capRadius={0.082 * s}\r\n          project={project}\r\n        />\r\n\r\n        {/* 近侧 */}\r\n        <Limb2D\r\n          pivot={[SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n          target={pose.footR}\r\n          bend={0.16}\r\n          maxLen={SPEC.legLen}\r\n          width={0.18 * s}\r\n          color={legColor}\r\n          capColor={legColor}\r\n          capRadius={0.105 * s}\r\n          capFlat={0.72}\r\n          project={project}\r\n        />\r\n        <Limb2D\r\n          pivot={[SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n          target={pose.handR}\r\n          bend={-0.16}\r\n          maxLen={SPEC.armLen}\r\n          width={0.17 * s}\r\n          color={armColor}\r\n          capColor={rig.belly}\r\n          capRadius={0.082 * s}\r\n          project={project}\r\n        />\r\n\r\n        {/* 球：画在近侧肢体之后——球在小熊身前，压住前臂才像\"手在球上\" */}\r\n        {dribble\r\n          ? (() => {\r\n              // 球是世界坐标，转成相对髋部的局部坐标再投影（dribble 的 rotZ=0，等价直传）\r\n              const bp = project([\r\n                dribble.ball[0] - root[0],\r\n                dribble.ball[1] - root[1],\r\n                dribble.ball[2],\r\n              ]);\r\n              const r = BALL_RADIUS * s;\r\n              const groundP = project([dribble.ball[0] - root[0], -root[1], dribble.ball[2]]);\r\n              return (\r\n                <g>\r\n                  <ellipse\r\n                    cx={groundP[0]}\r\n                    cy={GROUND_Y}\r\n                    rx={r * (0.9 - (dribble.ball[1] - 0.27) * 0.3)}\r\n                    ry={r * 0.26}\r\n                    fill=\"#1b2a33\"\r\n                    opacity={clamp(0.2 - (dribble.ball[1] - 0.27) * 0.18, 0.04, 0.2)}\r\n                  />\r\n                  <g transform={`translate(${bp[0]} ${bp[1]}) scale(${1 / dribble.squash} ${dribble.squash})`}>\r\n                    <circle r={r} fill=\"#ef5f58\" stroke=\"#c8443e\" strokeWidth={5} />\r\n                    {/* 球缝画在球面内部：画成外圈的弧会被读成\"红色球带蓝边\" */}\r\n                    <path\r\n                      d={`M ${-r * 0.96} ${-r * 0.16} Q 0 ${r * 0.5} ${r * 0.96} ${-r * 0.16}`}\r\n                      fill=\"none\"\r\n                      stroke={accent}\r\n                      strokeWidth={r * 0.13}\r\n                      opacity={0.85}\r\n                    />\r\n                    <path\r\n                      d={`M ${-r * 0.18} ${-r * 0.97} Q ${r * 0.42} 0 ${-r * 0.18} ${r * 0.97}`}\r\n                      fill=\"none\"\r\n                      stroke={accent}\r\n                      strokeWidth={r * 0.13}\r\n                      opacity={0.85}\r\n                    />\r\n                  </g>\r\n                </g>\r\n              );\r\n            })()\r\n          : null}\r\n      </svg>\r\n\r\n      {/* 名条：与 3D 舞台同一位置（左上），不压地面也不压字幕 */}\r\n      {scene.label ? (\r\n        <div\r\n          style={{\r\n            position: 'absolute',\r\n            left: 64,\r\n            top: 132,\r\n            padding: '8px 26px',\r\n            borderRadius: 999,\r\n            background: accent,\r\n            color: '#fff',\r\n            fontSize: 34,\r\n            fontWeight: 900,\r\n            whiteSpace: 'nowrap',\r\n            boxShadow: '0 8px 18px rgba(0,0,0,0.16)',\r\n          }}\r\n        >\r\n          {scene.label}\r\n        </div>\r\n      ) : null}\r\n\r\n      {/* 覆盖层：对话气泡这类 HTML 元素挂在角色之上。\r\n          出场时刻可延后（overlayFrom）：多动作幕里，气泡从第一帧就挂着等于剧透，\r\n          孩子还没看到\"指\"，台词已经先出现了。 */}\r\n      {scene.overlay ? (\r\n        <div\r\n          style={{\r\n            position: 'absolute',\r\n            inset: 0,\r\n            opacity:\r\n              scene.overlayFrom === undefined\r\n                ? 1\r\n                : clamp((frame / totalFrames - scene.overlayFrom) / 0.04, 0, 1),\r\n          }}\r\n        >\r\n          {scene.overlay}\r\n        </div>\r\n      ) : null}\r\n\r\n      {/* 越界自检：climb 的参数如果给得太高，角色会顶出画面。\r\n          这里不做自动缩放（那会让同一部片子里角色忽大忽小），\r\n          只把状态暴露给上层——渲染服务的抽帧检查会看到这个标记。 */}\r\n      {top < 90 ? <div data-puppet-warning=\"head-cropped\" style={{ display: 'none' }} /> : null}\r\n    </div>\r\n  );\r\n};\r\n"
  },
  {
    "path": "three/ThreeActionStage.tsx",
    "content": "/**\r\n * 三维动作舞台（方案 A：纯代码参数化 3D）\r\n *\r\n * 这份文件是 3D 舞台的唯一实现来源。它同时被两处使用：\r\n *  1. 后端生成的任务目录：buildGeneratedLessonTsx() 通过 three-stage-template.ts\r\n *     把它原样写进 .generated/remotion-tasks/task-<id>/three/ThreeActionStage.tsx，\r\n *     GeneratedLesson 再 import 进来；\r\n *  2. 本地预览：src/__preview3d 直接 import 本文件，用来抽帧验收。\r\n * 改完这里要跑 `npm run sync:three-stage`（backend）把模板串同步过去。\r\n *\r\n * 为什么全用几何体而不加载模型：\r\n * 滑梯和拍球的关键不是\"像不像真熊\"，而是\"身体贴着滑面\"\"掌球同帧接触\"。\r\n * 几何体拼出来的角色有真实的头/躯干/四肢与关节枢轴，四肢用\"从肩到目标点\"\r\n * 的定向算法定位，接触点因此是算出来的而不是画上去的。\r\n *\r\n * 确定性约束（Remotion 硬要求，改这个文件时务必守住）：\r\n *  - 只用 useCurrentFrame() 推帧，禁止 useFrame / requestAnimationFrame / delta；\r\n *  - 禁止 Math.random()、Date.now()、performance.now()；\r\n *  - 禁止自带时钟的 drei helper（Float / Sparkles / Stars / Trail …）；\r\n *  - 阴影不用实时阴影贴图（无头 WebGL 下帧序与耗时都不可控），用贴地圆片假阴影。\r\n */\r\n\r\nimport React from \"react\";\r\nimport { ThreeCanvas } from \"@remotion/three\";\r\nimport { useVideoConfig } from \"remotion\";\r\n// 姿态解算在 character/pose.ts（与渲染器无关）。这个文件只负责\"把关节目标点\r\n// 画成圆柱和四元数\"，不负责\"角色该怎么动\"——那是 pose 层的事。\r\nimport {\r\n  BALL_RADIUS,\r\n  SPEC,\r\n  clamp,\r\n  dribblePose,\r\n  slidePose,\r\n  type Pose,\r\n  type Tri,\r\n} from \"../character/pose\";\r\n// 取景规则与布景几何都在 character/ 下：相机不再是\"每个动作一组魔法数字\"，\r\n// 而是由景别（worldHeight + shot）反推，地面永远落在 STAGE.groundY。\r\nimport { framingFor, shotForMotion, STAGE, type Shot } from \"../character/stage-layout\";\r\nimport { LADDER, SLIDE, actorHeadTop, slideWorldHeight } from \"../character/setpiece\";\r\n\r\nexport type ThreeRig = {\r\n  fur: string;\r\n  belly: string;\r\n  ears: \"round\" | \"long\" | \"pointy\" | \"flap\" | \"none\";\r\n  tail: \"stub\" | \"long\" | \"bushy\";\r\n  scale: number;\r\n};\r\n\r\nexport type ThreeStageScene = {\r\n  motion: \"slide\" | \"dribble\";\r\n  /** GLB 分支用；程序化分支只拿它做日志与标签 */\r\n  actorId: string;\r\n  rig: ThreeRig;\r\n  start: [number, number, number];\r\n  end: [number, number, number];\r\n  bounce?: { periodFrames: number; height: number };\r\n  ballRestY?: number;\r\n  durationFrames: number;\r\n  accent: string;\r\n  label?: string;\r\n};\r\n\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 取景\r\n *\r\n * 相机不再有\"按动作写死的一套参数\"（曾经是 slide: z=8/lookY=1.55、\r\n * dribble: z=6.2/lookY=1.15）。那套写法有两个后果：地面行跟着动作跳\r\n * （2D 856、3D 827），以及\"结构再高一点就出画\"无法自动处理。\r\n *\r\n * 现在只由取景定律给一个 ppu，相机距离与 lookY 反推：\r\n *   屏幕Y = 540 + lookY * ppu ⇒ lookY = (地面行 − 540) / ppu\r\n *   z = 1080 / (2 * ppu * tan(fov/2))\r\n *\r\n * 注意：不能用 camera.position.y 抬高视角——R3F 的默认相机会 lookAt(0,0,0)，\r\n * 抬高相机等于让画面俯视，地面会被拉到中线。相机留在 y=0，把世界下移 lookY。\r\n * ------------------------------------------------------------------ */\r\n\r\n\r\n/**\r\n * 把一根肢体从 from 指向 to：返回中点位置、四元数（+Y 轴指向目标方向）、\r\n * 圆柱段长度。用四元数解析式而不是逐帧建 Object3D.lookAt，\r\n * 省掉一份可变的场景对象，也保证同样输入永远同样结果。\r\n */\r\nfunction limb(from: Tri, to: Tri) {\r\n  const dx = to[0] - from[0];\r\n  const dy = to[1] - from[1];\r\n  const dz = to[2] - from[2];\r\n  const len = Math.sqrt(dx * dx + dy * dy + dz * dz) || 0.0001;\r\n  const ux = dx / len;\r\n  const uy = dy / len;\r\n  const uz = dz / len;\r\n  // q ∝ (cross(a,b), 1 + a·b)，其中 a=(0,1,0)\r\n  const cx = uz;\r\n  const cz = -ux;\r\n  const w = 1 + uy;\r\n  const n = Math.sqrt(cx * cx + w * w + cz * cz) || 1;\r\n  const quaternion: [number, number, number, number] =\r\n    w < 1e-6 ? [1, 0, 0, 0] : [cx / n, 0, cz / n, w / n];\r\n  return {\r\n    position: [(from[0] + to[0]) / 2, (from[1] + to[1]) / 2, (from[2] + to[2]) / 2] as Tri,\r\n    quaternion,\r\n    length: len,\r\n  };\r\n}\r\n\r\n/** 一段肢体：胶囊体（圆柱段留出两端半球，避免关节处露缝） */\r\nconst Limb: React.FC<{\r\n  from: Tri;\r\n  to: Tri;\r\n  radius: number;\r\n  color: string;\r\n  /** 末端球（手掌/脚掌） */\r\n  capColor?: string;\r\n  capRadius?: number;\r\n  /**\r\n   * 最大长度。目标点超出这个距离时沿方向钳制——手要够球，但手臂不能被拉长：\r\n   * 拉长的手臂在画面上是\"橡皮人\"，比够不到更糟。当前动作的目标点都在\r\n   * 0.45 以内，这里只是安全网（斜接道具或极端时长时才起作用）。\r\n   */\r\n  maxLength?: number;\r\n}> = ({ from, to, radius, color, capColor, capRadius, maxLength }) => {\r\n  let target: Tri = to;\r\n  if (maxLength) {\r\n    const dx = to[0] - from[0];\r\n    const dy = to[1] - from[1];\r\n    const dz = to[2] - from[2];\r\n    const len = Math.sqrt(dx * dx + dy * dy + dz * dz);\r\n    if (len > maxLength) {\r\n      const k = maxLength / len;\r\n      target = [from[0] + dx * k, from[1] + dy * k, from[2] + dz * k];\r\n    }\r\n  }\r\n  const g = limb(from, target);\r\n  const bodyLen = Math.max(0.01, g.length - radius * 1.4);\r\n  const cap = capRadius ?? radius * 1.25;\r\n  return (\r\n    <group>\r\n      <mesh position={g.position} quaternion={g.quaternion}>\r\n        <capsuleGeometry args={[radius, bodyLen, 6, 14]} />\r\n        <meshStandardMaterial color={color} roughness={0.85} metalness={0} />\r\n      </mesh>\r\n      {capColor ? (\r\n        <mesh position={target}>\r\n          <sphereGeometry args={[cap, 12, 12]} />\r\n          <meshStandardMaterial color={capColor} roughness={0.8} metalness={0} />\r\n        </mesh>\r\n      ) : null}\r\n    </group>\r\n  );\r\n};\r\n\r\nconst Ears: React.FC<{ rig: ThreeRig; headY: number; headR: number }> = ({ rig, headY, headR }) => {\r\n  const y = headY + headR * 0.72;\r\n  const x = headR * 0.62;\r\n  const color = rig.fur;\r\n  if (rig.ears === \"none\") return null;\r\n  if (rig.ears === \"long\") {\r\n    return (\r\n      <group>\r\n        {[-1, 1].map((side) => (\r\n          <mesh key={side} position={[side * x * 0.7, y + 0.2, -0.02]} scale={[1, 1, 0.55]}>\r\n            <capsuleGeometry args={[0.075, 0.26, 5, 10]} />\r\n            <meshStandardMaterial color={color} roughness={0.85} />\r\n          </mesh>\r\n        ))}\r\n      </group>\r\n    );\r\n  }\r\n  if (rig.ears === \"pointy\") {\r\n    return (\r\n      <group>\r\n        {[-1, 1].map((side) => (\r\n          <mesh key={side} position={[side * x * 0.9, y, -0.01]} rotation={[0, 0, side * 0.32]}>\r\n            <coneGeometry args={[0.1, 0.22, 10]} />\r\n            <meshStandardMaterial color={color} roughness={0.85} />\r\n          </mesh>\r\n        ))}\r\n      </group>\r\n    );\r\n  }\r\n  if (rig.ears === \"flap\") {\r\n    return (\r\n      <group>\r\n        {[-1, 1].map((side) => (\r\n          <mesh\r\n            key={side}\r\n            position={[side * (headR + 0.12), headY + 0.02, 0]}\r\n            scale={[0.5, 1, 1]}\r\n          >\r\n            <sphereGeometry args={[0.19, 14, 14]} />\r\n            <meshStandardMaterial color={color} roughness={0.85} />\r\n          </mesh>\r\n        ))}\r\n      </group>\r\n    );\r\n  }\r\n  return (\r\n    <group>\r\n      {[-1, 1].map((side) => (\r\n        <mesh key={side} position={[side * x, y, 0]} scale={[1, 1, 0.6]}>\r\n          <sphereGeometry args={[0.115, 14, 14]} />\r\n          <meshStandardMaterial color={color} roughness={0.85} />\r\n        </mesh>\r\n      ))}\r\n    </group>\r\n  );\r\n};\r\n\r\nconst Tail: React.FC<{ rig: ThreeRig; swing: number }> = ({ rig, swing }) => {\r\n  if (rig.tail === \"stub\") {\r\n    return (\r\n      <mesh position={[0, -0.02, -0.28]}>\r\n        <sphereGeometry args={[0.11, 12, 12]} />\r\n        <meshStandardMaterial color={rig.belly} roughness={0.9} />\r\n      </mesh>\r\n    );\r\n  }\r\n  if (rig.tail === \"bushy\") {\r\n    return (\r\n      <mesh position={[0, 0.12, -0.36]} rotation={[0.5, 0, swing * 0.4]} scale={[0.8, 1.2, 0.9]}>\r\n        <sphereGeometry args={[0.17, 14, 14]} />\r\n        <meshStandardMaterial color={rig.fur} roughness={0.9} />\r\n      </mesh>\r\n    );\r\n  }\r\n  return (\r\n    <mesh position={[0.03, 0.1, -0.3]} rotation={[0.7, 0, swing * 0.5]} scale={[0.55, 1, 0.55]}>\r\n      <capsuleGeometry args={[0.06, 0.22, 5, 10]} />\r\n      <meshStandardMaterial color={rig.fur} roughness={0.9} />\r\n    </mesh>\r\n  );\r\n};\r\n\r\n\r\nconst ProceduralChar: React.FC<{ rig: ThreeRig; pose: Pose }> = ({ rig, pose }) => {\r\n  const s = rig.scale;\r\n  return (\r\n    <group position={pose.root} rotation={[0, pose.rotY, pose.rotZ]} scale={[s, s, s]}>\r\n      {/* 躯干 */}\r\n      <mesh position={[0, 0.16, 0]} scale={[1, 1.05, 0.85]}>\r\n        <capsuleGeometry args={[SPEC.torsoR, 0.24, 8, 18]} />\r\n        <meshStandardMaterial color={rig.fur} roughness={0.88} />\r\n      </mesh>\r\n      {/* 肚皮 */}\r\n      <mesh position={[0, 0.1, 0.2]} scale={[0.72, 0.82, 0.4]}>\r\n        <sphereGeometry args={[SPEC.torsoR, 16, 16]} />\r\n        <meshStandardMaterial color={rig.belly} roughness={0.9} />\r\n      </mesh>\r\n      {/* 头 */}\r\n      <mesh position={[0, SPEC.headY, 0.02]} rotation={[pose.headTilt, 0, 0]}>\r\n        <sphereGeometry args={[SPEC.headR, 20, 20]} />\r\n        <meshStandardMaterial color={rig.fur} roughness={0.88} />\r\n      </mesh>\r\n      {/* 口鼻 + 鼻头 + 眼睛 */}\r\n      <mesh position={[0, SPEC.headY - 0.07, SPEC.headR * 0.82]} scale={[1, 0.78, 0.85]}>\r\n        <sphereGeometry args={[0.135, 16, 16]} />\r\n        <meshStandardMaterial color={rig.belly} roughness={0.92} />\r\n      </mesh>\r\n      <mesh position={[0, SPEC.headY - 0.03, SPEC.headR * 1.12]}>\r\n        <sphereGeometry args={[0.058, 12, 12]} />\r\n        <meshStandardMaterial color=\"#3b2a20\" roughness={0.7} />\r\n      </mesh>\r\n      {[-1, 1].map((side) => (\r\n        <mesh key={side} position={[side * 0.108, SPEC.headY + 0.075, SPEC.headR * 0.9]}>\r\n          <sphereGeometry args={[0.036, 10, 10]} />\r\n          <meshStandardMaterial color=\"#241812\" roughness={0.6} />\r\n        </mesh>\r\n      ))}\r\n      <Ears rig={rig} headY={SPEC.headY} headR={SPEC.headR} />\r\n      <Tail rig={rig} swing={pose.tailSwing} />\r\n      {/* 四肢：肩/髋为共同枢轴，末端用目标点定向 */}\r\n      <Limb\r\n        from={[-SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n        to={pose.handL}\r\n        radius={0.082}\r\n        color={rig.fur}\r\n        capColor={rig.belly}\r\n        capRadius={0.095}\r\n        maxLength={SPEC.armLen}\r\n      />\r\n      <Limb\r\n        from={[SPEC.shoulder[0], SPEC.shoulder[1], SPEC.shoulder[2]]}\r\n        to={pose.handR}\r\n        radius={0.082}\r\n        color={rig.fur}\r\n        capColor={rig.belly}\r\n        capRadius={0.095}\r\n        maxLength={SPEC.armLen}\r\n      />\r\n      <Limb\r\n        from={[-SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n        to={pose.footL}\r\n        radius={0.095}\r\n        color={rig.fur}\r\n        capColor={rig.fur}\r\n        capRadius={0.11}\r\n        maxLength={SPEC.legLen}\r\n      />\r\n      <Limb\r\n        from={[SPEC.hipJoint[0], SPEC.hipJoint[1], SPEC.hipJoint[2]]}\r\n        to={pose.footR}\r\n        radius={0.095}\r\n        color={rig.fur}\r\n        capColor={rig.fur}\r\n        capRadius={0.11}\r\n        maxLength={SPEC.legLen}\r\n      />\r\n    </group>\r\n  );\r\n};\r\n\r\n/** 贴地假阴影：一个压扁的圆片，无实时阴影贴图，帧序无关 */\r\nconst Blob: React.FC<{ x: number; z: number; y?: number; r: number; opacity: number }> = ({\r\n  x,\r\n  z,\r\n  y = 0.012,\r\n  r,\r\n  opacity,\r\n}) => (\r\n  <mesh position={[x, y, z]} rotation={[-Math.PI / 2, 0, 0]} scale={[r, r * 0.55, 1]}>\r\n    <circleGeometry args={[1, 24]} />\r\n    <meshBasicMaterial color=\"#1b2a33\" transparent opacity={opacity} />\r\n  </mesh>\r\n);\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 道具：滑梯\r\n *\r\n * 几何全部来自 character/setpiece.ts。这里只做\"参数 → mesh\"的翻译，\r\n * 因为\"平台多厚、护边多高\"同时决定取景高度（见 slideWorldHeight），\r\n * 两处各写一份，就会出现\"画面装下了结构、取景却算矮了\"的分裂。\r\n * ------------------------------------------------------------------ */\r\nconst SlideRig: React.FC<{ start: Tri; end: Tri }> = ({ start, end }) => {\r\n  const dx = end[0] - start[0];\r\n  const dy = end[1] - start[1];\r\n  const len = Math.sqrt(dx * dx + dy * dy) || 1;\r\n  const angle = Math.atan2(dy, dx);\r\n  const mid: Tri = [(start[0] + end[0]) / 2, (start[1] + end[1]) / 2, 0];\r\n  const deckColor = \"#ffb347\";\r\n  const railColor = \"#ff8f4d\";\r\n  const postColor = \"#cf9a63\";\r\n  return (\r\n    <group>\r\n      {/* 滑面 */}\r\n      <mesh position={mid} rotation={[0, 0, angle]}>\r\n        <boxGeometry args={[len, SLIDE.deckThickness, SLIDE.deckWidth]} />\r\n        <meshStandardMaterial color={deckColor} roughness={0.7} />\r\n      </mesh>\r\n      {/* 两侧护边 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh\r\n          key={side}\r\n          position={[mid[0], mid[1] + SLIDE.railLift, side * SLIDE.railHalf]}\r\n          rotation={[0, 0, angle]}\r\n        >\r\n          <boxGeometry args={[len, SLIDE.railHeight, SLIDE.railThickness]} />\r\n          <meshStandardMaterial color={railColor} roughness={0.65} />\r\n        </mesh>\r\n      ))}\r\n      {/* 顶端平台 */}\r\n      <mesh position={[start[0] - Math.cos(angle) * SLIDE.platformInset, start[1] + SLIDE.platformThickness / 2, 0]}>\r\n        <boxGeometry args={[SLIDE.platformWidth, SLIDE.platformThickness, SLIDE.deckWidth]} />\r\n        <meshStandardMaterial color={deckColor} roughness={0.7} />\r\n      </mesh>\r\n      {/* 顶端支柱：只留两根，四根会把左侧糊成一片栅栏 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh\r\n          key={`post-${side}`}\r\n          position={[start[0] - Math.cos(angle) * SLIDE.topPostInset, start[1] / 2 - SLIDE.postLift, side * SLIDE.topPostHalfZ]}\r\n        >\r\n          <cylinderGeometry args={[SLIDE.topPostRadius, SLIDE.topPostRadius, Math.max(0.3, start[1] - SLIDE.topPostFoot), 10]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n      {/* 底端支柱：滑道末端离地 0.3，不撑起来就是一块悬空的板 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh key={`end-post-${side}`} position={[end[0] - SLIDE.endPostInset, end[1] / 2, side * SLIDE.endPostHalfZ]}>\r\n          <cylinderGeometry args={[SLIDE.endPostRadius, SLIDE.endPostRadius, Math.max(0.12, end[1] - SLIDE.endPostFoot), 10]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n      {/* 爬梯：两根立杆（左右分开，正面才看得出是梯子）+ 横档 */}\r\n      {[-1, 1].map((side) => (\r\n        <mesh\r\n          key={`ladder-${side}`}\r\n          position={[start[0] - Math.cos(angle) * SLIDE.ladderInset + side * LADDER.sideRailHalf, start[1] / 2 - SLIDE.postLift, 0]}\r\n        >\r\n          <cylinderGeometry args={[LADDER.sidePostRadius, LADDER.sidePostRadius, Math.max(0.5, start[1] - SLIDE.ladderFoot), 8]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n      {Array.from({ length: LADDER.sideRungs }).map((_, i) => (\r\n        <mesh\r\n          key={`rung-${i}`}\r\n          position={[\r\n            start[0] - Math.cos(angle) * SLIDE.ladderInset,\r\n            LADDER.sideRungStart + i * ((Math.max(0.5, start[1] - 0.3) - LADDER.sideRungStart) / (LADDER.sideRungs - 1)),\r\n            0,\r\n          ]}\r\n          rotation={[0, 0, Math.PI / 2]}\r\n        >\r\n          <cylinderGeometry args={[LADDER.sideRungRadius, LADDER.sideRungRadius, LADDER.sideRungLength, 8]} />\r\n          <meshStandardMaterial color={postColor} roughness={0.8} />\r\n        </mesh>\r\n      ))}\r\n    </group>\r\n  );\r\n};\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 道具：球\r\n *\r\n * 缝线不是\"套一个环\"：torus 的管心落在球面上，就会有一半管子突出轮廓，\r\n * 从侧面看是一圈蓝边（之前那版 radius*0.99 + tube 0.05*radius 就是这个问题，\r\n * 视觉上像给红球描了个蓝边，而不是缝）。正确做法是让 torus 外缘正好等于\r\n * 球半径：major = r - tube，管子嵌进表面，只露出贴近表面的一段。\r\n * ------------------------------------------------------------------ */\r\nconst Ball: React.FC<{ position: Tri; radius: number; squash: number; spin: number }> = ({\r\n  position,\r\n  radius,\r\n  squash,\r\n  spin,\r\n}) => (\r\n  <group position={position} rotation={[spin, 0, 0]} scale={[1 / squash, squash, 1 / squash]}>\r\n    <mesh>\r\n      <sphereGeometry args={[radius, 32, 24]} />\r\n      <meshStandardMaterial color=\"#ef5f58\" roughness={0.55} />\r\n    </mesh>\r\n    {[0, Math.PI / 2].map((rot) => (\r\n      <mesh key={rot} rotation={[rot, 0, 0]}>\r\n        <torusGeometry args={[radius * 0.955, radius * 0.045, 8, 48]} />\r\n        <meshStandardMaterial color=\"#b8382f\" roughness={0.5} />\r\n      </mesh>\r\n    ))}\r\n  </group>\r\n);\r\n\r\n\r\n/* ------------------------------------------------------------------ *\r\n * 舞台\r\n * ------------------------------------------------------------------ */\r\nexport const ThreeActionStage: React.FC<{\r\n  scene: ThreeStageScene;\r\n  /** 场景局部帧（由 GeneratedLesson 的 useLocalFrame 传入，不用 useCurrentFrame：\r\n   *  收尾窗口里画面要被钉在冻结帧上，否则最后一秒会自己动起来） */\r\n  frame: number;\r\n  /** 景别覆盖。不给就按动作判定：slide → wide，dribble → medium */\r\n  shot?: Shot;\r\n}> = ({ scene, frame, shot: shotOverride }) => {\r\n  const { width, height } = useVideoConfig();\r\n  const accent = scene.accent || \"#4d96ff\";\r\n  const isSlide = scene.motion === \"slide\";\r\n  const scale = scene.rig.scale || 1;\r\n\r\n  /**\r\n   * 取景：滑梯要装下\"结构 + 平台上的坐姿角色\"（contentHeight），\r\n   * 而\"角色该画多大\"只看站立身高（subjectHeight）——把坐姿高度当主体尺寸，\r\n   * 滑梯会被无谓推远。地面行固定，所以 2D/3D 之间切换时脚不会上下跳。\r\n   */\r\n  const subjectHeight = actorHeadTop(SPEC.standHipY, Math.max(1, scale));\r\n  const worldHeight = isSlide\r\n    ? slideWorldHeight(scene.start, scene.end, Math.max(1, scale))\r\n    : subjectHeight;\r\n  const shot = shotOverride ?? shotForMotion(scene.motion);\r\n  const view = framingFor({ contentHeight: worldHeight, subjectHeight }, shot).camera;\r\n\r\n  const slide = isSlide ? slidePose(scene, frame) : null;\r\n  const dribble = isSlide ? null : dribblePose(scene, frame);\r\n  const pose = slide || dribble!.pose;\r\n\r\n  return (\r\n    <div style={{ position: \"absolute\", inset: 0 }}>\r\n      <ThreeCanvas\r\n        width={width}\r\n        height={height}\r\n        camera={{ position: [0, 0, view.z], fov: view.fov, near: 0.1, far: 100 }}\r\n        style={{ position: \"absolute\", inset: 0, background: \"transparent\" }}\r\n      >\r\n        <ambientLight intensity={0.95} />\r\n        <directionalLight position={[4, 7, 6]} intensity={1.15} />\r\n        <directionalLight position={[-5, 3, -4]} intensity={0.35} />\r\n\r\n        {/* 世界整体下移 lookY：相机留在 y=0，靠位移把地面压到屏幕下方 */}\r\n        <group position={[0, -view.lookY, 0]}>\r\n          <ProceduralChar rig={scene.rig} pose={pose} />\r\n\r\n          {isSlide ? <SlideRig start={scene.start} end={scene.end} /> : null}\r\n\r\n          {dribble ? (\r\n            <>\r\n              <Ball\r\n                position={dribble.ball}\r\n                radius={BALL_RADIUS}\r\n                squash={dribble.squash}\r\n                spin={dribble.spin}\r\n              />\r\n              <Blob\r\n                x={dribble.ball[0]}\r\n                z={dribble.ball[2]}\r\n                r={clamp(0.42 - (dribble.ball[1] - 0.27) * 0.12, 0.18, 0.42)}\r\n                opacity={clamp(0.3 - (dribble.ball[1] - 0.27) * 0.12, 0.06, 0.3)}\r\n              />\r\n              <Blob x={pose.root[0]} z={pose.root[2]} r={0.5} opacity={0.22} />\r\n            </>\r\n          ) : null}\r\n        </group>\r\n      </ThreeCanvas>\r\n\r\n      {/* 角色名条：3D 里画不了可读文字，用 DOM 覆盖。\r\n          贴在标题带下沿（不是写死 132）：角色名和标题是同一条信息带的\r\n          两级，摆在不同来源的坐标上，改标题字号就会撞。 */}\r\n      {scene.label ? (\r\n        <div\r\n          style={{\r\n            position: \"absolute\",\r\n            left: 64,\r\n            top: STAGE.titleBandBottom + 8,\r\n            padding: \"8px 26px\",\r\n            borderRadius: 999,\r\n            background: accent,\r\n            color: \"#fff\",\r\n            fontSize: 34,\r\n            fontWeight: 900,\r\n            whiteSpace: \"nowrap\",\r\n            boxShadow: \"0 8px 18px rgba(0,0,0,0.16)\",\r\n          }}\r\n        >\r\n          {scene.label}\r\n        </div>\r\n      ) : null}\r\n    </div>\r\n  );\r\n};\r\n"
  }
];
